import {ActionMenu, ActionList, Stack} from '@primer/react'
import {RepoIcon, ChecklistIcon} from '@primer/octicons-react'
import {QuickSetupApplyTo} from '../../../security-products-enablement-types'
import styles from '../SettingsStep.module.css'

export type ApplyToDropdownVariant = 'default' | 'largeConfig'

const APPLY_TO_LABELS: Record<QuickSetupApplyTo, string> = {
  [QuickSetupApplyTo.All]: 'All repositories',
  [QuickSetupApplyTo.Selected]: 'Selected repositories',
  [QuickSetupApplyTo.NotApplicable]: 'Selected repositories',
  [QuickSetupApplyTo.None]: 'None',
}

function getApplyToIcon(applyTo: QuickSetupApplyTo) {
  if (applyTo === QuickSetupApplyTo.All) return <RepoIcon size={16} aria-hidden="true" />
  if (applyTo === QuickSetupApplyTo.Selected) return <ChecklistIcon size={16} aria-hidden="true" />
  if (applyTo === QuickSetupApplyTo.NotApplicable) return <ChecklistIcon size={16} aria-hidden="true" />
  return null
}

interface ApplyToDropdownProps {
  applyTo: QuickSetupApplyTo
  onApplyToChange: (value: QuickSetupApplyTo) => void
  variant?: ApplyToDropdownVariant
}

/**
 * Shared dropdown component for selecting which repositories to apply configuration to.
 * Used by all three ApplyToSection variants.
 */
export function ApplyToDropdown({applyTo, onApplyToChange, variant = 'default'}: ApplyToDropdownProps) {
  const options = [
    QuickSetupApplyTo.All,
    variant === 'largeConfig' ? QuickSetupApplyTo.NotApplicable : QuickSetupApplyTo.Selected,
    QuickSetupApplyTo.None,
  ]

  return (
    <Stack direction="horizontal" align="center">
      <div id="apply-to-label" className={styles.settingLabel}>
        Apply to
      </div>
      <ActionMenu>
        <ActionMenu.Button aria-labelledby="apply-to-label">
          {getApplyToIcon(applyTo)} {APPLY_TO_LABELS[applyTo]}
        </ActionMenu.Button>
        <ActionMenu.Overlay>
          <ActionList selectionVariant="single" aria-label="Apply to">
            {options.map(value => (
              <ActionList.Item
                key={value}
                selected={value === applyTo}
                aria-checked={value === applyTo}
                onSelect={() => onApplyToChange(value)}
              >
                {APPLY_TO_LABELS[value]}
              </ActionList.Item>
            ))}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </Stack>
  )
}
