export const GHAS_SKUS = {
  bundled: {
    name: 'GitHub Advanced Security',
    perActiveCommitter: '$49/active committer.',
    perMonth: '$49/month',
  },
  secretProtection: {
    name: 'Secret Protection',
    bundledName: 'Secret scanning',
    perActiveCommitter: '$19/active committer.',
    perMonth: '$19/month',
  },
  codeSecurity: {
    name: 'Code Security',
    bundledName: 'Code scanning',
    perActiveCommitter: '$30/active committer.',
    perMonth: '$30/month',
  },
} as const

export type GhasSku = keyof typeof GHAS_SKUS

export function skuNames(skus: GhasSku[]): string {
  return skus.map(k => GHAS_SKUS[k].name).join(' and ')
}

export function skuIsPlural(skus: GhasSku[]): boolean {
  return skus.length > 1
}

export function skuVerb(skus: GhasSku[], singular: string, plural: string): string {
  return skuIsPlural(skus) ? plural : singular
}
