import {Banner} from '@primer/react'
import type {Capabilities} from '../security-products-enablement-types'

const UsageLockedBanner = ({capabilities, userNamespace}: {capabilities: Capabilities; userNamespace: boolean}) => {
  const {advancedSecurity} = capabilities
  const advancedSecurityLocked = advancedSecurity.bundled && advancedSecurity.advancedSecurityEnablementLocked
  const secretProtectionLocked = !advancedSecurity.bundled && advancedSecurity.secretProtection.enablementLocked
  const codeSecurityLocked = !advancedSecurity.bundled && advancedSecurity.codeSecurity.enablementLocked

  if (!advancedSecurityLocked && !secretProtectionLocked && !codeSecurityLocked && !userNamespace) {
    return null
  }

  if (!advancedSecurityLocked && !secretProtectionLocked && userNamespace) {
    return null
  }

  const lockReason = advancedSecurityLocked
    ? advancedSecurity.advancedSecurityEnablementLockReason
    : secretProtectionLocked
      ? advancedSecurity.secretProtection.enablementLockReason
      : advancedSecurity.codeSecurity.enablementLockReason

  const description =
    lockReason === 'BudgetExhausted'
      ? 'GitHub Advanced Security features cannot be enabled on additional repositories because your enterprise admin has set a budget limit. Please contact your enterprise admin to adjust the budget.'
      : 'GitHub Advanced Security features cannot be enabled on additional repositories due to a billing issue. Configurations for existing repositories can be managed as usual. After resolving the issue, please allow a few minutes for changes to apply.'

  return (
    <Banner
      description={description}
      title="Enablement locked for new repositories"
      variant="info"
      data-testid="security-configs-enablement-locked-banner"
      className="tmp-mb-3"
    />
  )
}

export default UsageLockedBanner
