import {useState, useMemo} from 'react'
import {useQuery, useQueryClient} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {settingsOrgQuickSetupSecurityConfigurationsRepositoriesPath} from '@github-ui/paths'
import {useDebounce} from '@github-ui/use-debounce'
import type {Repository, RepositoryPickerState} from '../security-products-enablement-types'

interface RepositoriesResponse {
  repositories: Repository[]
  total_repository_count: number
}

interface UseQuickSetupRepositoriesOptions {
  org: string
}

// Merges repositories from all cached filter queries into a single lookup map.
// When the user filters the repository list, selected repos may disappear from
// the current API response. By merging all cached queries, we preserve repo
// metadata (especially license committer IDs) for selected repos even when
// they're hidden by the active filter.
function mergeAllCachedRepositories(
  cachedResponses: RepositoriesResponse[],
  currentResponse?: RepositoriesResponse,
): Map<number, Repository> {
  const reposById = new Map<number, Repository>()

  for (const cachedData of cachedResponses) {
    for (const repo of cachedData.repositories) {
      reposById.set(repo.id, repo)
    }
  }

  // Current response takes precedence (fresher data)
  if (currentResponse) {
    for (const repo of currentResponse.repositories) {
      reposById.set(repo.id, repo)
    }
  }

  return reposById
}

// Manages debounced filter input. Returns both the immediate value (for input
// display) and the debounced value (for triggering API calls).
function useDebouncedFilter(delayMs = 300) {
  const [displayValue, setDisplayValue] = useState('')
  const [queryValue, setQueryValue] = useState('')

  const debouncedSetQueryValue = useDebounce((value: string) => setQueryValue(value.trim()), delayMs)

  const onChange = (value: string) => {
    setDisplayValue(value)
    debouncedSetQueryValue(value)
  }

  return {displayValue, queryValue, onChange}
}

// Fetches and manages repository data for the quick-setup flow.
// Composed by useQuickSetupForm - not intended for direct use.
export function useQuickSetupRepositories({org}: UseQuickSetupRepositoriesOptions) {
  const queryClient = useQueryClient()
  const filter = useDebouncedFilter()

  const {data, isLoading, isError} = useQuery({
    queryKey: ['quick-setup', 'repositories', org, filter.queryValue],
    queryFn: async () => {
      const url = new URL(settingsOrgQuickSetupSecurityConfigurationsRepositoriesPath({org}), window.location.origin)
      url.searchParams.set('q', filter.queryValue)

      const response = await reactFetchJSON(url.toString())
      if (!response.ok) {
        throw new Error()
      }

      return (await response.json()) as RepositoriesResponse
    },
  })

  const reposById = useMemo(() => {
    const cachedQueries = queryClient.getQueriesData<RepositoriesResponse>({
      queryKey: ['quick-setup', 'repositories', org],
    })
    // Extract responses from cache, filtering out pending/failed queries
    const cachedResponses = cachedQueries.flatMap(([, r]) => (r ? [r] : []))
    return mergeAllCachedRepositories(cachedResponses, data)
  }, [data, org, queryClient])

  return {
    org,
    repositories: data?.repositories ?? [],
    reposById,
    totalCount: data?.total_repository_count ?? 0,
    isLoading,
    isError,
    filterValue: filter.displayValue,
    onFilterChange: filter.onChange,
  } satisfies RepositoryPickerState
}
