import {Blankslate} from '@primer/react/experimental'
import {settingsOrgSecurityConfigurationsQuickSetupPath} from '@github-ui/paths'
import {GHAS_SKUS} from './ghas-skus'

interface QuickSetupBlankslateProps {
  organization: string
  aboutGHASUrl: string
  isBundled: boolean
}

export function QuickSetupBlankslate({organization, aboutGHASUrl, isBundled}: QuickSetupBlankslateProps) {
  return (
    <Blankslate border data-testid="quick-setup-blankslate">
      <Blankslate.Heading>Set up Advanced Security</Blankslate.Heading>
      <Blankslate.Description>
        Manage {isBundled ? GHAS_SKUS.secretProtection.bundledName : GHAS_SKUS.secretProtection.name},{' '}
        {isBundled ? GHAS_SKUS.codeSecurity.bundledName : GHAS_SKUS.codeSecurity.name} and Dependabot.
      </Blankslate.Description>
      <Blankslate.PrimaryAction href={settingsOrgSecurityConfigurationsQuickSetupPath({org: organization})}>
        Set up
      </Blankslate.PrimaryAction>
      <Blankslate.SecondaryAction href={aboutGHASUrl}>Learn more</Blankslate.SecondaryAction>
    </Blankslate>
  )
}
