import {AlertIcon} from '@primer/octicons-react'
import pluralize from 'pluralize'
import type {WarningState} from '../../hooks/use-warning-state'
import {skuNames, skuVerb} from './ghas-skus'
import styles from './ReviewStep.module.css'

interface ReviewStepWarningProps {
  warning: WarningState
}

export function ReviewStepWarning({warning}: ReviewStepWarningProps) {
  const {title, subtitle} = getWarningContent(warning)

  return (
    <div className={styles.warningMessage} data-testid="review-step-warning">
      <div className={styles.warningTitle}>
        <AlertIcon size={16} className="color-fg-attention" />
        <strong>{title}</strong>
      </div>
      <div className="color-fg-muted">{subtitle}</div>
    </div>
  )
}

function getWarningContent(warning: WarningState): {title: string; subtitle: string} {
  switch (warning.kind) {
    case 'policy-restricted':
      return {
        title: `${skuNames(warning.products)} ${skuVerb(warning.products, 'is', 'are')} blocked by an enterprise policy.`,
        subtitle: 'Private repositories will only have free features enabled.',
      }

    case 'enablement-locked':
      return {
        title: `${skuNames(warning.products)} features cannot be enabled on additional repositories due to a billing issue.`,
        subtitle: 'Configurations for existing repositories can be managed as usual.',
      }

    case 'not-purchased':
      return {
        title: `${skuNames(warning.products)} ${skuVerb(warning.products, 'is', 'are')} not purchased in your enterprise.`,
        subtitle: 'Private repositories will only have free features enabled.',
      }

    case 'overage': {
      return {
        title: `Your organization has exceeded its ${skuNames(warning.products)} license limit by ${warning.exceededLicenses} ${pluralize('license', warning.exceededLicenses)}.`,
        subtitle: 'Private repositories will only have free features enabled.',
      }
    }

    case 'not-enough-seats': {
      return {
        title: `${warning.licensesToPurchase} additional ${skuNames(warning.products)} ${pluralize('license', warning.licensesToPurchase)} needed.`,
        subtitle: 'Private repositories will only have free features enabled.',
      }
    }
  }
}
