import {useQuery} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {settingsOrgQuickSetupSecurityConfigurationsAdditionalLicenseUsagePath} from '@github-ui/paths'
import type {LicenseUsage} from '../security-products-enablement-types'

interface UseAdditionalLicenseUsageOptions {
  org: string
  enabled?: boolean
}

/**
 * Fetches the additional license usage that would be incurred by enabling all unbundled SKUs
 * across all repositories in the organization.
 *
 * This is used when the user selects "Apply to all repositories" to show the total additional
 * license count without needing to enumerate individual repositories.
 */
export function useAdditionalLicenseUsage({org, enabled = true}: UseAdditionalLicenseUsageOptions) {
  const {data, isLoading, isFetching, isError, refetch} = useQuery({
    queryKey: ['quick-setup', 'additional-license-usage', org],
    queryFn: async () => {
      const url = settingsOrgQuickSetupSecurityConfigurationsAdditionalLicenseUsagePath({org})

      const response = await reactFetchJSON(url)
      if (!response.ok) {
        throw new Error('Failed to fetch additional license usage')
      }

      return (await response.json()) as LicenseUsage
    },
    enabled,
  })

  const defaultLicenseUsage: LicenseUsage = {
    secret_protection: {license_count: 0},
    code_security: {license_count: 0},
  }

  return {
    licenseUsage: data ?? defaultLicenseUsage,
    // Use isFetching to show loading state during both initial load and refetches
    isLoading: isLoading || isFetching,
    isError,
    refetch,
  }
}
