import {Banner} from '@primer/react'
import {testIdProps} from '@github-ui/test-id-props'
import {useAppContext} from '../contexts/AppContext'

export function TrialBanner({className}: {className?: string}) {
  const {
    capabilities: {advancedSecurity},
  } = useAppContext()

  if (advancedSecurity.bundled) return null

  const {secretProtection, codeSecurity} = advancedSecurity

  let trialText = ''
  if (secretProtection.onTrial && codeSecurity.onTrial) {
    if (secretProtection.trialExpiresAt === codeSecurity.trialExpiresAt) {
      trialText = `You are currently on a GitHub Advanced Security trial until ${secretProtection.trialExpiresAt}. No charges will be incurred during that trial.`
    } else {
      trialText = `You are currently on a GitHub Secret Protection trial until ${secretProtection.trialExpiresAt} and a Code Security trial until ${codeSecurity.trialExpiresAt}. No charges will be incurred during those trials.`
    }
  } else if (secretProtection.onTrial) {
    trialText = `You are currently on a GitHub Secret Protection trial until ${secretProtection.trialExpiresAt}. No charges will be incurred during that trial.`
  } else if (codeSecurity.onTrial) {
    trialText = `You are currently on a GitHub Code Security trial until ${codeSecurity.trialExpiresAt}. No charges will be incurred during that trial.`
  } else {
    return null
  }

  return (
    <Banner
      className={className}
      title="GitHub Trial"
      hideTitle
      description={trialText}
      variant="info"
      {...testIdProps('trial-banner')}
    />
  )
}
