import {useAppContext} from '../contexts/AppContext'
import {QuickSetupSettingValue} from '../security-products-enablement-types'
import type {
  LicenseCounts,
  OrganizationLicensePayload,
  QuickSetupFormState,
} from '../security-products-enablement-types'
import type {GhasSku} from '../components/QuickSetup/ghas-skus'

interface WarningBase {
  products: GhasSku[]
}

export type WarningState =
  | (WarningBase & {kind: 'policy-restricted'})
  | (WarningBase & {kind: 'enablement-locked'})
  | (WarningBase & {kind: 'not-purchased'})
  | (WarningBase & {kind: 'overage'; exceededLicenses: number})
  | (WarningBase & {kind: 'not-enough-seats'; licensesToPurchase: number; remainingLicenses: number})

interface UseWarningStateArgs {
  formState: Pick<QuickSetupFormState, 'secretProtection' | 'codeSecurity'>
  licenses?: OrganizationLicensePayload
  additionalLicenseCounts?: LicenseCounts
}

function affectedSkus(sp: boolean, cs: boolean): GhasSku[] {
  const skus: GhasSku[] = []
  if (sp) skus.push('secretProtection')
  if (cs) skus.push('codeSecurity')
  return skus
}

export function useWarningState({
  formState,
  licenses,
  additionalLicenseCounts,
}: UseWarningStateArgs): WarningState | null {
  const {
    capabilities: {advancedSecurity},
  } = useAppContext()

  const bundled = advancedSecurity.bundled

  // For unbundled, not_set means "don't change" — only warn for SKUs actively being enabled
  const spChanging =
    formState.secretProtection === QuickSetupSettingValue.Enabled ||
    formState.secretProtection === QuickSetupSettingValue.Custom
  const csChanging =
    formState.codeSecurity === QuickSetupSettingValue.Enabled ||
    formState.codeSecurity === QuickSetupSettingValue.Custom

  // Gate: no warning if all paid features are disabled
  if (
    formState.secretProtection === QuickSetupSettingValue.Disabled &&
    formState.codeSecurity === QuickSetupSettingValue.Disabled
  )
    return null

  // --- Priority 1: Not purchased ---
  if (bundled && !advancedSecurity.purchased) {
    return {kind: 'not-purchased', products: ['bundled']}
  }

  if (!bundled) {
    const spMissing = !advancedSecurity.secretProtection.purchased && spChanging
    const csMissing = !advancedSecurity.codeSecurity.purchased && csChanging

    if (spMissing || csMissing) {
      return {kind: 'not-purchased', products: affectedSkus(spMissing, csMissing)}
    }
  }

  // --- Priority 2: Policy restricted ---
  if (bundled && advancedSecurity.bundledAdvancedSecurity.orgRestrictedByEnterprisePolicy) {
    return {kind: 'policy-restricted', products: ['bundled']}
  }

  if (!bundled) {
    const spRestricted = advancedSecurity.secretProtection.orgRestrictedByEnterprisePolicy && spChanging
    const csRestricted = advancedSecurity.codeSecurity.orgRestrictedByEnterprisePolicy && csChanging

    if (spRestricted || csRestricted) {
      return {kind: 'policy-restricted', products: affectedSkus(spRestricted, csRestricted)}
    }
  }

  // --- Priority 3: Enablement locked (billing issue) ---
  if (bundled && advancedSecurity.advancedSecurityEnablementLocked) {
    return {kind: 'enablement-locked', products: ['bundled']}
  }

  if (!bundled) {
    const spLocked = advancedSecurity.secretProtection.enablementLocked && spChanging
    const csLocked = advancedSecurity.codeSecurity.enablementLocked && csChanging

    if (spLocked || csLocked) {
      return {kind: 'enablement-locked', products: affectedSkus(spLocked, csLocked)}
    }
  }

  // Overage and not-enough-seats require successfully loaded license data
  const hasLicenseData = licenses && !licenses.failedToFetchLicenses
  if (!hasLicenseData) return null

  // --- Priority 4: Overage ---
  if (bundled && licenses.bundled?.allowanceExceeded) {
    return {
      kind: 'overage',
      products: ['bundled'],
      exceededLicenses: licenses.bundled.exceededSeats,
    }
  }

  if (!bundled) {
    const spExceeded = licenses.secret_protection?.allowanceExceeded && spChanging
    const csExceeded = licenses.code_security?.allowanceExceeded && csChanging

    if (spExceeded || csExceeded) {
      const products = affectedSkus(!!spExceeded, !!csExceeded)

      const totalExceeded =
        (spExceeded ? licenses.secret_protection!.exceededSeats : 0) +
        (csExceeded ? licenses.code_security!.exceededSeats : 0)

      return {kind: 'overage', products, exceededLicenses: totalExceeded}
    }
  }

  // --- Priority 5: Not enough seats ---
  if (!additionalLicenseCounts) return null

  if (bundled && licenses.bundled && !licenses.bundled.hasUnlimitedSeats) {
    const {remainingSeats: remainingLicenses} = licenses.bundled
    const needed = additionalLicenseCounts.bundledCount
    if (needed > 0 && needed > remainingLicenses) {
      return {
        kind: 'not-enough-seats',
        products: ['bundled'],
        licensesToPurchase: needed - remainingLicenses,
        remainingLicenses,
      }
    }
  }

  if (!bundled) {
    const spNeeded = additionalLicenseCounts.secretProtectionCount
    const csNeeded = additionalLicenseCounts.codeSecurityCount
    const spRemaining = licenses.secret_protection?.remainingSeats ?? 0
    const csRemaining = licenses.code_security?.remainingSeats ?? 0
    const spInsufficient =
      spChanging && spNeeded > 0 && spNeeded > spRemaining && !licenses.secret_protection?.hasUnlimitedSeats
    const csInsufficient =
      csChanging && csNeeded > 0 && csNeeded > csRemaining && !licenses.code_security?.hasUnlimitedSeats

    if (spInsufficient || csInsufficient) {
      const products = affectedSkus(spInsufficient, csInsufficient)

      const totalNeeded = (spInsufficient ? spNeeded : 0) + (csInsufficient ? csNeeded : 0)
      const totalRemaining = (spInsufficient ? spRemaining : 0) + (csInsufficient ? csRemaining : 0)

      return {
        kind: 'not-enough-seats',
        products,
        licensesToPurchase: totalNeeded - totalRemaining,
        remainingLicenses: totalRemaining,
      }
    }
  }

  return null
}
