import {useState, useCallback} from 'react'
import {useSearchParams} from '@github-ui/use-navigate'
import {QueryState, type TabType} from '../utils/query-state'

interface UseTabQueryStateReturn {
  activeTab: TabType
  queryState: QueryState
  switchTab: (tab: TabType) => void
  updateQuery: (query: string, page: number) => QueryState
}

/**
 * Manages the tab ↔ query string interaction for the security products page.
 *
 * Owns: activeTab, queryState, URL serialization.
 * Does NOT own: data fetching, repositories, loading state.
 *
 * Key invariants (see spec.md):
 * - `q` and `page` are scoped to the repositories tab.
 * - Switching to configurations strips `q`/`page` from the URL but preserves them in memory.
 * - Switching back to repositories restores the last `q`/`page` from memory.
 */
export function useTabQueryState(): UseTabQueryStateReturn {
  const [searchParams] = useSearchParams()

  // Derive initial state from URL
  const [activeTab, setActiveTab] = useState<TabType>(() => {
    return QueryState.restoreFromSearchParams(searchParams).tab
  })

  // repoQueryState holds the last query/page used on the repos tab — survives tab switches.
  const [repoQueryState, setRepoQueryState] = useState<QueryState>(() =>
    QueryState.restoreFromSearchParams(searchParams),
  )

  const switchTab = useCallback(
    (tab: TabType) => {
      setActiveTab(tab)

      if (tab === 'configurations') {
        // Strip q/page from URL, keep them in repoQueryState
        const urlState = new QueryState('configurations')
        urlState.persistToHistory()
      } else {
        // Restore q/page from the in-memory repoQueryState
        const urlState = new QueryState('repositories', repoQueryState.query, repoQueryState.page)
        urlState.persistToHistory()
      }
    },
    [repoQueryState],
  )

  const updateQuery = useCallback((query: string, page: number): QueryState => {
    const newState = new QueryState('repositories', query, page)
    newState.persistToHistory()
    setRepoQueryState(newState)
    return newState
  }, [])

  return {
    activeTab,
    queryState: repoQueryState,
    switchTab,
    updateQuery,
  }
}
