import type {SecurityConfigurationSettings, SecurityFeature} from '../security-products-enablement-types'
import rulesJson from '../data/security-configuration-rules.json'

/**
 * SKU policies control how a feature responds when its parent SKU toggle is flipped:
 * - enable_on_sku:    feature is force-enabled when the SKU is turned on
 * - preserve_on_sku:  feature keeps the user's prior Enabled choice; defaults to NotSet otherwise
 * - recommend_on_sku: feature is enabled only if the server flagged it as recommended for this config
 */
export type SkuPolicy = 'enable_on_sku' | 'preserve_on_sku' | 'recommend_on_sku'

/** The two purchasable product bundles. Each feature in the tree belongs to exactly one. */
export type UnbundledSku = 'code_security' | 'secret_protection'

/** The combined GHAS toggle that covers all unbundled SKUs. */
export type BundledSku = 'bundled_ghas'

/** A SKU selector: the bundled GHAS toggle (all SKUs) or a single unbundled SKU. */
export type Sku = BundledSku | UnbundledSku

/**
 * One node in the feature dependency tree.
 * `parent`/`children` encode the hierarchy (e.g. secretScanning → secretScanningPushProtection).
 * `sku` ties the feature to a purchasable bundle; `skuPolicy` decides the enable/disable behavior.
 */
export interface FeatureRule {
  feature: SecurityFeature
  parent: SecurityFeature | null
  children: SecurityFeature[]
  sku: UnbundledSku | undefined
  skuPolicy: SkuPolicy | null
  /** Settings key that holds the server-supplied "recommended" flag for recommend_on_sku features. */
  recommendedFlag: keyof SecurityConfigurationSettings | null
}

export type FeatureRuleMap = Record<SecurityFeature, FeatureRule>

/**
 * Encapsulates the JSON-derived feature dependency tree and provides
 * traversal helpers used by the reducer and UI components.
 *
 * Built once at module load from the shared JSON that is also consumed
 * by the Ruby backend — adding a new feature to the JSON automatically
 * wires it into the client-side cascade without any TypeScript code changes.
 */
export class FeatureTree {
  readonly #rules: FeatureRuleMap
  readonly hierarchyOrder: SecurityFeature[]
  readonly #skuFeatures: Map<Sku, readonly FeatureRule[]>

  constructor() {
    this.#rules = this.#buildRules()
    this.hierarchyOrder = this.#buildHierarchyOrder()
    this.#skuFeatures = this.#buildSkuFeatures()
  }

  get(feature: SecurityFeature): FeatureRule {
    return this.#rules[feature]
  }

  /** Paid features belonging to the given SKU, in hierarchy order. */
  featuresForSku(sku: Sku): readonly FeatureRule[] {
    return this.#skuFeatures.get(sku) ?? []
  }

  /** Walk the ancestor chain from feature upward (excluding the feature itself). */
  *ancestors(feature: SecurityFeature): Iterable<SecurityFeature> {
    let current = this.#rules[feature].parent
    while (current) {
      yield current
      current = this.#rules[current].parent
    }
  }

  /** Breadth-first walk of all descendants, yielding [child, parent] tuples. */
  *descendants(feature: SecurityFeature): Iterable<[SecurityFeature, SecurityFeature]> {
    const queue: Array<[SecurityFeature, SecurityFeature]> = this.#rules[feature].children.map(c => [c, feature])
    let entry: [SecurityFeature, SecurityFeature] | undefined
    while ((entry = queue.shift())) {
      const [current, parent] = entry
      yield [current, parent]
      for (const child of this.#rules[current].children) {
        queue.push([child, current])
      }
    }
  }

  #buildRules(): FeatureRuleMap {
    const result = {} as FeatureRuleMap
    const features = rulesJson.features as Record<
      string,
      {parent: string | null; sku: string | null; skuPolicy?: string}
    >

    for (const [key, rule] of Object.entries(features)) {
      const featureKey = key as SecurityFeature
      const skuPolicy = (rule.skuPolicy as SkuPolicy) ?? null
      const recommendedFlag =
        skuPolicy === 'recommend_on_sku' ? (`${featureKey}Recommended` as keyof SecurityConfigurationSettings) : null
      result[featureKey] = {
        feature: featureKey,
        parent: (rule.parent as SecurityFeature) ?? null,
        children: [],
        sku: (rule.sku as UnbundledSku) ?? undefined,
        skuPolicy,
        recommendedFlag,
      }
    }

    for (const rule of Object.values(result)) {
      if (rule.parent) {
        result[rule.parent].children.push(rule.feature)
      }
    }

    return result
  }

  /**
   * Breadth-first search from root features (no parent). Parents appear before children
   * so that cascade logic can read an already-resolved parent value.
   */
  #buildHierarchyOrder(): SecurityFeature[] {
    const order: SecurityFeature[] = []
    const roots = Object.values(this.#rules)
      .filter(rule => rule.parent === null)
      .map(rule => rule.feature)

    const queue = [...roots]
    while (queue.length > 0) {
      const current = queue.shift()!
      order.push(current)
      for (const child of this.#rules[current].children) {
        queue.push(child)
      }
    }
    return order
  }

  #buildSkuFeatures(): Map<Sku, readonly FeatureRule[]> {
    const allPaid: FeatureRule[] = []
    const bySku = new Map<UnbundledSku, FeatureRule[]>()

    for (const feature of this.hierarchyOrder) {
      const rule = this.#rules[feature]
      if (!rule.sku) continue
      allPaid.push(rule)
      let skuList = bySku.get(rule.sku)
      if (!skuList) {
        skuList = []
        bySku.set(rule.sku, skuList)
      }
      skuList.push(rule)
    }

    const result = new Map<Sku, readonly FeatureRule[]>()
    result.set('bundled_ghas', allPaid)
    for (const [sku, features] of bySku) {
      result.set(sku, features)
    }
    return result
  }
}

export const featureTree = new FeatureTree()
