import {Button, Flash, Link} from '@primer/react'
import {clsx} from 'clsx'
import {StartTrialDialog} from '@github-ui/licensing-advanced-security-overview/components/StartTrialDialog'
import type {SelfServeTrialInfo} from '@github-ui/licensing-advanced-security-overview/types/self-serve-trial-info'
import {NavigationContextProvider} from '@github-ui/licensing-common/contexts/NavigationContext'
import {useStartTrialDialog} from '../../hooks/use-start-trial-dialog'
import type {UpsellType} from '../../security-products-enablement-types'

import {CONTACT_SALES_URL} from '../../utils/constants'

import styles from '../../routes/EnterpriseSettings.module.css'

export interface UpsellCTAProps {
  upsellType: UpsellType
  selfServeTrialInfo?: SelfServeTrialInfo
  className?: string
}

export function UpsellCTA({upsellType, selfServeTrialInfo, className}: UpsellCTAProps) {
  const {
    showDialog,
    isStartingTrial,
    errorMessage,
    enterpriseSlug,
    ghasFeaturesUrl,
    openDialog,
    closeDialog,
    confirmStart,
  } = useStartTrialDialog({selfServeTrialInfo})

  // Volume customers see a "Contact sales" CTA
  if (upsellType === 'volume_contact_sales') {
    return (
      <p className={clsx(styles.UpsellCTA, className)} data-testid="upsell-cta">
        <Link href={CONTACT_SALES_URL} className={styles.UpsellCTAButton}>
          Contact sales
        </Link>{' '}
        to upgrade to Advanced Security.
      </p>
    )
  }

  // For trial CTA, we need selfServeTrialInfo
  if (upsellType !== 'trial' || !selfServeTrialInfo) {
    return null
  }

  return (
    <>
      {errorMessage && (
        <Flash variant="danger" className="mb-2">
          {errorMessage}
        </Flash>
      )}
      <p className={clsx(styles.UpsellCTA, className)} data-testid="upsell-cta">
        This enterprise is eligible for a free {selfServeTrialInfo.trialDays}-day trial of Advanced Security.{' '}
        <Button variant="link" onClick={openDialog} className={styles.UpsellCTAButton}>
          Start it now
        </Button>
        .
      </p>

      {showDialog && (
        <NavigationContextProvider slug={enterpriseSlug} enterpriseContactUrl="">
          <StartTrialDialog
            onClose={closeDialog}
            onConfirmStart={confirmStart}
            isStartingTrial={isStartingTrial}
            selfServeTrialInfo={selfServeTrialInfo}
            ghasFeaturesUrl={ghasFeaturesUrl}
          />
        </NavigationContextProvider>
      )}
    </>
  )
}
