import {useState, useCallback, useEffect, useMemo, useRef} from 'react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {
  settingsOrgQuickSetupSecurityConfigurationsCreatePath,
  settingsOrgQuickSetupSecurityConfigurationPath,
} from '@github-ui/paths'
import {
  QuickSetupSettingValue,
  QuickSetupApplyTo,
  QuickSetupDialogMode,
  QuickSetupDefaultForNewRepos,
} from '../security-products-enablement-types'
import type {
  QuickSetupFormState,
  QuickSetupCreatePayload,
  QuickSetupConfigResponse,
  QuickSetupDialogModeType,
  RepositorySelection,
} from '../security-products-enablement-types'
import {useQuickSetupRepositories} from './use-quick-setup-repositories'
import {useAppContext} from '../contexts/AppContext'
import {getQuickSetupProductAvailability, type QuickSetupProductAvailability} from '../utils/helpers'

interface InitialFormStateOptions {
  isFirstConfig?: boolean
  productAvailability: QuickSetupProductAvailability
}

export const getInitialFormState = ({
  isFirstConfig = false,
  productAvailability,
}: InitialFormStateOptions): QuickSetupFormState => ({
  secretProtection: productAvailability.secretProtection
    ? QuickSetupSettingValue.Enabled
    : QuickSetupSettingValue.Disabled,
  codeSecurity: productAvailability.codeSecurity ? QuickSetupSettingValue.Enabled : QuickSetupSettingValue.Disabled,
  dependabot: productAvailability.dependabot ? QuickSetupSettingValue.Enabled : QuickSetupSettingValue.Disabled,
  applyTo: isFirstConfig ? QuickSetupApplyTo.All : QuickSetupApplyTo.Selected,
  selectedRepoIds: new Set<number>(),
  repoOwnerCanModify: false,
  defaultForNewRepos: isFirstConfig ? QuickSetupDefaultForNewRepos.All : QuickSetupDefaultForNewRepos.None,
  isNotApplicable: false,
})

interface BuildPayloadOptions {
  formState: QuickSetupFormState
  settingsReadOnly?: boolean
  dialogMode: QuickSetupDialogModeType
  productAvailability: QuickSetupProductAvailability
}

export const buildPayload = ({
  formState,
  settingsReadOnly = false,
  dialogMode,
  productAvailability,
}: BuildPayloadOptions): QuickSetupCreatePayload => {
  let repositorySelection: RepositorySelection

  switch (formState.applyTo) {
    case QuickSetupApplyTo.All:
      repositorySelection = 'all'
      break
    case QuickSetupApplyTo.None:
      repositorySelection = 'none'
      break
    case QuickSetupApplyTo.NotApplicable:
      repositorySelection = 'not_applicable'
      break
    case QuickSetupApplyTo.Selected:
      repositorySelection = formState.selectedRepoIds.size > 0 ? Array.from(formState.selectedRepoIds) : 'none'
      break
    default:
      assertNever(formState.applyTo)
  }

  const payload: QuickSetupCreatePayload = {
    repository_selection: repositorySelection,
    enforced: !formState.repoOwnerCanModify,
    default_for_new_repositories: formState.defaultForNewRepos,
  }

  if (!settingsReadOnly) {
    const includeUnavailableProducts = dialogMode === QuickSetupDialogMode.NEW
    if (includeUnavailableProducts || productAvailability.secretProtection) {
      payload.secret_protection = formState.secretProtection
    }
    if (includeUnavailableProducts || productAvailability.codeSecurity) {
      payload.code_security = formState.codeSecurity
    }
    if (includeUnavailableProducts || productAvailability.dependabot) {
      payload.dependabot = formState.dependabot
    }
  }

  return payload
}

// Helper for exhaustive checking - TypeScript will error if a case is missed
function assertNever(value: never): never {
  throw new Error(`Unexpected value: ${value}`)
}

/**
 * Maps the backend repository_selection response to form state values.
 * - "all" → All repositories selected
 * - "none" → No repositories selected (unless there are failed attachments)
 * - "not_applicable" → >500 repos, can't enumerate (applyTo will be NotApplicable, isNotApplicable will be true)
 * - number[] → Specific repos selected (pre-populate picker)
 *
 * When failedReposCount > 0 and repository_selection is 'none', the config still has
 * repos attached (they just failed), so we treat it as "Selected repositories" instead of "None".
 */
export function mapRepositorySelectionToFormState(
  repositorySelection: RepositorySelection,
  failedReposCount = 0,
): {
  applyTo: QuickSetupApplyTo
  selectedRepoIds: Set<number>
  isNotApplicable: boolean
} {
  // Handle array case first (specific repos selected)
  if (Array.isArray(repositorySelection)) {
    return {
      applyTo: QuickSetupApplyTo.Selected,
      selectedRepoIds: new Set<number>(repositorySelection),
      isNotApplicable: false,
    }
  }

  // Now repositorySelection is narrowed to 'all' | 'none' | 'not_applicable'
  switch (repositorySelection) {
    case 'all':
      return {
        applyTo: QuickSetupApplyTo.All,
        selectedRepoIds: new Set<number>(),
        isNotApplicable: false,
      }
    case 'none':
      return {
        applyTo: failedReposCount > 0 ? QuickSetupApplyTo.Selected : QuickSetupApplyTo.None,
        selectedRepoIds: new Set<number>(),
        isNotApplicable: false,
      }
    case 'not_applicable':
      return {
        applyTo: QuickSetupApplyTo.NotApplicable,
        selectedRepoIds: new Set<number>(),
        isNotApplicable: true,
      }
    default:
      return assertNever(repositorySelection)
  }
}

interface UseQuickSetupFormOptions {
  org: string
  onSuccess: () => void
  dialogMode: QuickSetupDialogModeType
  settingsReadOnly?: boolean
  configurationId?: number
  isFirstConfig?: boolean
  failedReposCount?: number
}

export function useQuickSetupForm({
  org,
  onSuccess,
  dialogMode,
  settingsReadOnly = false,
  configurationId,
  isFirstConfig = false,
  failedReposCount = 0,
}: UseQuickSetupFormOptions) {
  const {securityProducts} = useAppContext()
  const productAvailability = useMemo(() => getQuickSetupProductAvailability(securityProducts), [securityProducts])
  const [formState, setFormState] = useState<QuickSetupFormState>(() =>
    getInitialFormState({isFirstConfig, productAvailability}),
  )
  const [isLoading, setIsLoading] = useState(dialogMode === QuickSetupDialogMode.EDIT && !!configurationId)
  const [isSaving, setIsSaving] = useState(false)
  const [isLoadError, setIsLoadError] = useState(false)
  const [isSaveError, setIsSaveError] = useState(false)
  const [originalConfig, setOriginalConfig] = useState<QuickSetupConfigResponse | null>(null)
  const hasFetchedRef = useRef(false)
  const repositoriesData = useQuickSetupRepositories({org})

  // Fetch existing configuration when in edit mode
  useEffect(() => {
    if (dialogMode !== QuickSetupDialogMode.EDIT || !configurationId) {
      return
    }

    // Prevent duplicate fetches (e.g., from React Strict Mode double-invoking effects)
    if (hasFetchedRef.current) {
      return
    }
    hasFetchedRef.current = true

    const fetchConfig = async () => {
      setIsLoading(true)

      try {
        const url = settingsOrgQuickSetupSecurityConfigurationPath({org, id: configurationId})
        const response = await verifiedFetchJSON(url, {method: 'GET'})

        if (!response.ok) {
          throw new Error()
        }

        const data = (await response.json()) as QuickSetupConfigResponse
        setOriginalConfig(data)

        // Map repository_selection to applyTo, selectedRepoIds, and isNotApplicable
        const {applyTo, selectedRepoIds, isNotApplicable} = mapRepositorySelectionToFormState(
          data.repository_selection,
          failedReposCount,
        )

        // Convert API response to form state - keep values as-is including 'custom'
        setFormState({
          secretProtection: data.secret_protection,
          codeSecurity: data.code_security,
          dependabot: data.dependabot,
          applyTo,
          selectedRepoIds,
          repoOwnerCanModify: !data.enforced,
          defaultForNewRepos: data.default_for_new_repositories,
          isNotApplicable,
        })
        setIsLoading(false)
      } catch {
        setIsLoadError(true)
        setIsLoading(false)
      }
    }

    fetchConfig()
  }, [dialogMode, configurationId, org, failedReposCount])

  const handleSave = useCallback(async () => {
    setIsSaving(true)
    setIsSaveError(false)
    const payload = buildPayload({formState, settingsReadOnly, dialogMode, productAvailability})
    const isUpdate = dialogMode === QuickSetupDialogMode.EDIT && configurationId

    try {
      const url = isUpdate
        ? settingsOrgQuickSetupSecurityConfigurationPath({org, id: configurationId})
        : settingsOrgQuickSetupSecurityConfigurationsCreatePath({org})
      const method = isUpdate ? 'PATCH' : 'POST'
      const response = await verifiedFetchJSON(url, {method, body: payload})

      if (!response.ok) {
        throw new Error()
      }

      onSuccess()
    } catch {
      setIsSaveError(true)
    } finally {
      setIsSaving(false)
    }
  }, [formState, org, onSuccess, dialogMode, configurationId, settingsReadOnly, productAvailability])

  return {
    formState,
    setFormState,
    handleSave,
    isLoading,
    isSaving,
    isLoadError,
    isSaveError,
    originalConfig,
    // Repository picker state bundled for easier prop threading
    repositoryPicker: repositoriesData,
  }
}
