import {useState, useCallback, startTransition} from 'react'
import {Button, Dialog, IconButton} from '@primer/react'
import {ArrowLeftIcon} from '@primer/octicons-react'
import {
  settingsOrgSecurityConfigurationsNewPath,
  settingsOrgSecurityConfigurationsEditPath,
  settingsOrgSecurityConfigurationsViewPath,
} from '@github-ui/paths'
import {Link} from '@github-ui/react-core/link'
import {SettingsStep} from './SettingsStep'
import {RepositoriesStep} from './RepositoriesStep'
import {ReviewStep} from './ReviewStep'
import {useQuickSetupForm} from '../../hooks/use-quick-setup-form'
import {useAdditionalLicenseUsage} from '../../hooks/use-additional-license-usage'
import {determineLicenseCounts} from '../../utils/determine-license-counts'
import {useSelectedLicenseCounts} from '../../hooks/use-selected-license-counts'
import {
  QuickSetupDialogMode,
  QuickSetupApplyTo,
  type QuickSetupDialogModeType,
  type OrganizationLicensePayload,
} from '../../security-products-enablement-types'
import {FooterLicenseCounts} from './FooterLicenseCounts'
import {useWarningState} from '../../hooks/use-warning-state'
import styles from './QuickSetupDialog.module.css'

type Step = 'settings' | 'repositories' | 'review'

interface QuickSetupDialogProps {
  onClose: () => void
  org: string
  dialogMode: QuickSetupDialogModeType
  settingsReadOnly?: boolean
  configurationId?: number
  originalAttachedRepoCount?: number
  failedReposCount?: number
  licenses?: OrganizationLicensePayload
}

export function QuickSetupDialog({
  onClose,
  org,
  dialogMode,
  settingsReadOnly = false,
  configurationId,
  originalAttachedRepoCount,
  failedReposCount,
  licenses,
}: QuickSetupDialogProps) {
  const {
    formState,
    setFormState,
    handleSave,
    isLoading,
    isSaving,
    isLoadError,
    isSaveError,
    originalConfig,
    repositoryPicker,
  } = useQuickSetupForm({
    org,
    onSuccess: onClose,
    dialogMode,
    settingsReadOnly,
    configurationId,
    failedReposCount,
  })

  const [currentStep, setCurrentStep] = useState<Step>('settings')
  const [isTransitioning, setIsTransitioning] = useState(false)

  // Use formState.selectedRepoIds directly instead of maintaining local state
  const selectedRepoIds = formState.selectedRepoIds

  // Fetch additional license usage for "Apply to all" scenario
  const {
    licenseUsage: allReposLicenseUsage,
    isLoading: isLoadingAllReposLicenses,
    isError: isAllReposLicensesError,
    refetch: refetchAllReposLicenses,
  } = useAdditionalLicenseUsage({
    org,
    enabled: formState.applyTo === QuickSetupApplyTo.All,
  })

  // Loading/error states only apply when "Apply to all" is selected
  const isLoadingLicenses = formState.applyTo === QuickSetupApplyTo.All && isLoadingAllReposLicenses
  const isLicensesError = formState.applyTo === QuickSetupApplyTo.All && isAllReposLicensesError

  // Calculate license counts for selected repositories (used in repositories step footer and as fallback)
  const selectedLicenseCounts = useSelectedLicenseCounts({
    selectedRepoIds,
    reposById: repositoryPicker.reposById,
  })

  // Determine license counts for review step:
  // - "All": API-provided counts
  // - "Selected": calculated from selected repos
  // - "NotApplicable": originalAttachedRepoCount for display, no license estimates
  const {repoCount, ...licenseCounts} = determineLicenseCounts({
    formState,
    forAllRepos: {
      repoCount: repositoryPicker.totalCount,
      licenseUsage: allReposLicenseUsage,
    },
    forSelectedRepos: {
      repoCount: selectedRepoIds.size,
      licenseCounts: selectedLicenseCounts,
    },
    originalAttachedRepoCount,
  })

  const warning = useWarningState({formState, licenses, additionalLicenseCounts: licenseCounts})

  // Wrapper to update formState when selection changes
  const handleSelectionChange = useCallback(
    (newSelectedRepoIds: Set<number>) => {
      setFormState(prev => ({...prev, selectedRepoIds: newSelectedRepoIds}))
    },
    [setFormState],
  )

  // Show repo step only when Selected is chosen AND we can actually enumerate repos
  // (isNotApplicable means config is attached to >500 repos, so we skip the repo picker)
  const showRepoStep = formState.applyTo === QuickSetupApplyTo.Selected && !formState.isNotApplicable

  const handleBackClick = () => {
    switch (currentStep) {
      case 'repositories':
        setCurrentStep('settings')
        break
      case 'review':
        setCurrentStep(showRepoStep ? 'repositories' : 'settings')
        break
    }
  }

  const handleNextClick = () => {
    switch (currentStep) {
      case 'settings':
        if (showRepoStep) {
          setIsTransitioning(true)
          setCurrentStep('repositories')
          startTransition(() => {
            setIsTransitioning(false)
          })
        } else {
          setCurrentStep('review')
        }
        break
      case 'repositories':
        setCurrentStep('review')
        break
    }
  }

  const handleCloseDialog = () => {
    setCurrentStep('settings')
    setFormState(prev => ({...prev, selectedRepoIds: new Set()}))
    setIsTransitioning(false)
    onClose()
  }

  const renderBackButton = (label: string) => (
    <IconButton
      aria-label={label}
      icon={ArrowLeftIcon}
      variant="invisible"
      size="small"
      onClick={handleBackClick}
      className="mr-1"
    />
  )

  const getDialogTitle = () => {
    switch (currentStep) {
      case 'settings':
        return dialogMode === QuickSetupDialogMode.NEW ? 'New configuration' : 'Edit configuration'
      case 'repositories':
        return (
          <div className="d-flex flex-items-center">
            {renderBackButton('Back to settings')}
            Select repositories
          </div>
        )
      case 'review':
        return (
          <div className="d-flex flex-items-center">
            {renderBackButton('Back to previous step')}
            Review configuration
          </div>
        )
    }
  }

  const renderDialogContent = () => {
    switch (currentStep) {
      case 'settings':
        return (
          <SettingsStep
            formState={formState}
            onFormStateChange={setFormState}
            isLoading={isLoading}
            isLoadError={isLoadError}
            dialogMode={dialogMode}
            originalConfig={originalConfig}
            settingsReadOnly={settingsReadOnly}
            licenses={licenses}
            warning={warning}
          />
        )
      case 'repositories':
        return (
          <RepositoriesStep
            selectedRepoIds={selectedRepoIds}
            onSelectionChange={handleSelectionChange}
            repositoryPicker={repositoryPicker}
            isTransitioning={isTransitioning}
            configurationId={configurationId}
          />
        )
      case 'review':
        return (
          <ReviewStep
            formState={formState}
            repoCount={repoCount}
            licenseCounts={licenseCounts}
            licenses={licenses}
            warning={warning}
            isSaveError={isSaveError}
            isLoadingLicenses={isLoadingLicenses}
            isLicensesError={isLicensesError}
            onRetryLicenses={refetchAllReposLicenses}
          />
        )
    }
  }

  let customConfigLink: string
  if (settingsReadOnly && configurationId) {
    customConfigLink = settingsOrgSecurityConfigurationsViewPath({org, id: configurationId})
  } else if (dialogMode === QuickSetupDialogMode.EDIT && configurationId) {
    customConfigLink = settingsOrgSecurityConfigurationsEditPath({org, id: configurationId})
  } else {
    customConfigLink = settingsOrgSecurityConfigurationsNewPath({org})
  }

  const customConfigLabel = settingsReadOnly ? 'View configuration' : 'Custom configuration'

  const isSaveDisabled = isLoading || isSaving || isLoadError

  const renderFooter = () => {
    switch (currentStep) {
      case 'settings':
        return (
          <div className={styles.dialogFooter}>
            <Button as={Link} to={customConfigLink} variant="invisible">
              {customConfigLabel}
            </Button>
            <Button variant="primary" onClick={handleNextClick} disabled={isSaveDisabled}>
              {showRepoStep ? 'Select repositories' : 'Review'}
            </Button>
          </div>
        )
      case 'repositories':
        return (
          <div className={styles.dialogFooterWithLicenses}>
            <FooterLicenseCounts licenseCounts={licenseCounts} licenses={licenses} />
            <div className={styles.dialogFooterButtons}>
              <Button onClick={handleCloseDialog}>Cancel</Button>
              <Button variant="primary" onClick={handleNextClick} count={selectedRepoIds.size || undefined}>
                Review
              </Button>
            </div>
          </div>
        )
      case 'review':
        return (
          <div className={styles.dialogFooter}>
            <Button onClick={handleCloseDialog}>Cancel</Button>
            <Button variant="primary" onClick={handleSave} disabled={isSaveDisabled}>
              Save and enable
            </Button>
          </div>
        )
    }
  }

  const renderBody = () => {
    // For the repositories step, we want no padding so the picker goes edge-to-edge
    // Other steps get default padding via their own wrapper
    if (currentStep === 'repositories') {
      return renderDialogContent()
    }
    return <div className="tmp-p-3">{renderDialogContent()}</div>
  }

  return (
    <Dialog
      title={getDialogTitle()}
      onClose={handleCloseDialog}
      renderFooter={renderFooter}
      renderBody={renderBody}
      data-testid="quick-setup-dialog"
      height={currentStep === 'repositories' ? 'large' : 'auto'}
      className={currentStep === 'repositories' ? styles.quickSetupDialog : undefined}
    />
  )
}
