import {Flash, Stack} from '@primer/react'
import {QuickSetupApplyTo, QuickSetupDefaultForNewRepos} from '../../security-products-enablement-types'
import type {
  LicenseCounts,
  OrganizationLicensePayload,
  QuickSetupFormState,
} from '../../security-products-enablement-types'
import type {WarningState} from '../../hooks/use-warning-state'
import {TrialBanner} from '../TrialBanner'
import styles from './ReviewStep.module.css'
import {ReviewStepLicenseSection} from './ReviewStepLicenseSection'

interface ReviewStepProps {
  formState: Pick<QuickSetupFormState, 'applyTo' | 'defaultForNewRepos'>
  repoCount: number
  licenseCounts: LicenseCounts
  licenses?: OrganizationLicensePayload
  warning?: WarningState | null
  isSaveError?: boolean
  isLoadingLicenses?: boolean
  isLicensesError?: boolean
  onRetryLicenses?: () => void
}

export function ReviewStep({
  formState,
  repoCount,
  licenseCounts,
  licenses,
  warning,
  isSaveError = false,
  isLoadingLicenses = false,
  isLicensesError = false,
  onRetryLicenses,
}: ReviewStepProps) {
  const {applyTo, defaultForNewRepos} = formState
  const isNotApplicable = applyTo === QuickSetupApplyTo.NotApplicable

  const newReposTextMap: Record<QuickSetupDefaultForNewRepos, string> = {
    [QuickSetupDefaultForNewRepos.All]: ' and all new repositories going forward',
    [QuickSetupDefaultForNewRepos.Public]: ' and all new public repositories going forward',
    [QuickSetupDefaultForNewRepos.Private]: ' and all new private and internal repositories going forward',
    [QuickSetupDefaultForNewRepos.None]: '',
  }

  const newReposText = newReposTextMap[defaultForNewRepos]

  return (
    <Stack gap="normal">
      {isSaveError ? (
        <Flash variant="danger">Something went wrong saving the configuration. Please try again.</Flash>
      ) : null}

      <TrialBanner />

      {/* Description */}
      <div>
        {isNotApplicable ? (
          <>
            These settings will apply to {repoCount} repositories attached to this configuration
            {newReposText} and could incur costs.
          </>
        ) : (
          <>
            These settings will apply to {repoCount} existing repositories
            {newReposText}.
          </>
        )}
      </div>

      {/* License estimates section - hidden for NotApplicable since we can't enumerate repos */}
      {!isNotApplicable && (
        <Stack direction="vertical" gap="none">
          <h3 className={styles.sectionHeader}>Additional estimated licenses</h3>

          <ReviewStepLicenseSection
            licenseCounts={licenseCounts}
            licenses={licenses}
            warning={warning}
            isLoadingLicenses={isLoadingLicenses}
            isLicensesError={isLicensesError}
            onRetryLicenses={onRetryLicenses}
          />
        </Stack>
      )}
    </Stack>
  )
}
