import {useState, useRef, useEffect, startTransition} from 'react'
import {IconButton, Button, Dialog} from '@primer/react'
import {PencilIcon} from '@primer/octicons-react'
import {QuickSetupApplyTo} from '../../../security-products-enablement-types'
import type {
  RepositoryPickerState,
  QuickSetupFormState,
  OrganizationLicensePayload,
} from '../../../security-products-enablement-types'
import {ApplyToDropdown} from './ApplyToDropdown'
import {RepositoriesStep} from '../RepositoriesStep'
import {FooterLicenseCounts} from '../FooterLicenseCounts'
import {useSelectedLicenseCounts} from '../../../hooks/use-selected-license-counts'
import {applySkuEnablementFiltering} from '../../../utils/determine-license-counts'
import dialogStyles from '../QuickSetupDialog.module.css'
import formStyles from '../SettingsStep.module.css'

interface ApplyToSectionInlinePickerProps {
  onApplyToChange: (value: QuickSetupApplyTo) => void
  repositoryPicker: RepositoryPickerState
  selectedRepoIds: Set<number>
  onSelectionChange: (ids: Set<number>) => void
  formState: QuickSetupFormState
  licenses?: OrganizationLicensePayload
}

/**
 * Apply To section for the page flow (first-time setup).
 * Shows dropdown, selected repository count, and an inline picker dialog
 * for selecting specific repositories.
 */
export function ApplyToSectionInlinePicker({
  onApplyToChange,
  repositoryPicker,
  selectedRepoIds,
  onSelectionChange,
  formState,
  licenses,
}: ApplyToSectionInlinePickerProps) {
  const [isRepoDialogOpen, setIsRepoDialogOpen] = useState(false)
  const [isTransitioning, setIsTransitioning] = useState(false)
  // Store the original selection when dialog opens so we can restore on cancel
  const originalSelectionRef = useRef<Set<number>>(new Set())

  useEffect(() => {
    return () => {
      originalSelectionRef.current.clear()
    }
  }, [])

  // Calculate license counts for selected repositories
  const selectedLicenseCounts = useSelectedLicenseCounts({
    selectedRepoIds,
    reposById: repositoryPicker.reposById,
  })

  // Apply SKU filtering: disabled SKUs don't require licenses
  const filteredLicenseCounts = applySkuEnablementFiltering(selectedLicenseCounts, formState)

  const showSelectedSubfield = formState.applyTo === QuickSetupApplyTo.Selected

  const handleOpenDialog = () => {
    originalSelectionRef.current = new Set(selectedRepoIds)
    setIsTransitioning(true)
    setIsRepoDialogOpen(true)
    startTransition(() => {
      setIsTransitioning(false)
    })
  }

  const handleCancel = () => {
    onSelectionChange(originalSelectionRef.current)
    setIsRepoDialogOpen(false)
  }

  const handleSave = () => {
    setIsRepoDialogOpen(false)
  }

  return (
    <>
      <div className={formStyles.applyToSettingRow}>
        <ApplyToDropdown applyTo={formState.applyTo} onApplyToChange={onApplyToChange} />

        {showSelectedSubfield && (
          <div className={formStyles.selectedReposRow} role="group" aria-labelledby="selected-repos-label">
            <div id="selected-repos-label" className={formStyles.settingLabel}>
              Selected repositories
            </div>
            <div id="selected-repos-count" className={formStyles.selectedReposCount} data-testid="selected-repos-count">
              {selectedRepoIds.size === 0
                ? 'No repositories selected'
                : `${selectedRepoIds.size} ${selectedRepoIds.size === 1 ? 'repository' : 'repositories'} selected`}
            </div>
            <IconButton
              icon={PencilIcon}
              aria-label="Edit selected repositories"
              aria-describedby="selected-repos-count"
              size="small"
              onClick={handleOpenDialog}
            />
          </div>
        )}
      </div>

      {isRepoDialogOpen && (
        <Dialog
          title={<div className="d-flex flex-items-center">Select repositories</div>}
          onClose={handleCancel}
          width="xlarge"
          height="large"
          className={dialogStyles.quickSetupDialog}
          renderBody={() => (
            <RepositoriesStep
              selectedRepoIds={selectedRepoIds}
              onSelectionChange={onSelectionChange}
              repositoryPicker={repositoryPicker}
              isTransitioning={isTransitioning}
            />
          )}
          renderFooter={() => (
            <div className={dialogStyles.dialogFooterWithLicenses}>
              <FooterLicenseCounts licenseCounts={filteredLicenseCounts} licenses={licenses} />
              <div className={dialogStyles.dialogFooterButtons}>
                <Button onClick={handleCancel}>Cancel</Button>
                <Button variant="primary" onClick={handleSave} count={selectedRepoIds.size || undefined}>
                  Save
                </Button>
              </div>
            </div>
          )}
        />
      )}
    </>
  )
}
