/**
 * Shared utilities for security coverage features.
 * Used by both EnterpriseSettings and OrganizationSettingsSecurityProducts.
 */

/**
 * Default query filter for coverage page links.
 *
 * We intentionally do NOT add feature-specific `:enabled` filters here. The usage cards
 * on the configurations page show "X% of repositories protected" which is calculated
 * from ALL repositories (enabled / total). When users click through, they should see
 * ALL repositories so the total count matches the denominator used in the percentage.
 * Adding `:enabled` would show only the numerator, causing a confusing discrepancy.
 */
export const COVERAGE_QUERY_FILTER = 'archived:false'

/**
 * Transform backend titles to display names based on licensing model.
 * Backend returns: Dependabot, Code scanning, Secret scanning
 * Bundled customers see backend titles as-is.
 * Unbundled customers see: Dependabot, Code Security, Secret Protection
 */
export function getDisplayTitle(backendTitle: string, isBundled: boolean): string {
  if (isBundled) {
    return backendTitle // Use backend titles as-is for bundled customers
  }
  // Transform titles for unbundled (metered) customers
  switch (backendTitle) {
    case 'Code scanning':
      return 'Code Security'
    case 'Secret scanning':
      return 'Secret Protection'
    default:
      return backendTitle
  }
}
