import {QuickSetupApplyTo, QuickSetupSettingValue} from '../security-products-enablement-types'
import type {LicenseCounts, LicenseUsage, QuickSetupFormState} from '../security-products-enablement-types'

/**
 * Apply SKU filtering to license counts.
 * Unbundled: returns 0 for disabled or not_set SKUs since they don't consume licenses.
 * Bundled: returns 0 only when both SKUs are disabled; not_set is still a paid state.
 */
export function applySkuEnablementFiltering(
  counts: LicenseCounts,
  formState: Pick<QuickSetupFormState, 'secretProtection' | 'codeSecurity'>,
): LicenseCounts {
  const spRequiresLicense =
    formState.secretProtection === QuickSetupSettingValue.Enabled ||
    formState.secretProtection === QuickSetupSettingValue.Custom
  const csRequiresLicense =
    formState.codeSecurity === QuickSetupSettingValue.Enabled ||
    formState.codeSecurity === QuickSetupSettingValue.Custom
  const spDisabled = formState.secretProtection === QuickSetupSettingValue.Disabled
  const csDisabled = formState.codeSecurity === QuickSetupSettingValue.Disabled
  return {
    secretProtectionCount: spRequiresLicense ? counts.secretProtectionCount : 0,
    codeSecurityCount: csRequiresLicense ? counts.codeSecurityCount : 0,
    bundledCount: spDisabled && csDisabled ? 0 : counts.bundledCount,
  }
}

interface ForAllReposCounts {
  repoCount: number
  licenseUsage: LicenseUsage
}

interface ForSelectedReposCounts {
  repoCount: number
  licenseCounts: LicenseCounts
}

/**
 * Determine license counts for the ReviewStep component.
 *
 * applyTo behavior:
 * - "All": uses API-provided counts from forAllRepos
 * - "Selected": uses calculated counts from forSelectedRepos
 * - "NotApplicable": uses originalAttachedRepoCount for repo count (license counts from forSelectedRepos)
 * - "None": returns 0 for all counts
 *
 * SKU filtering (unbundled):
 * - If secretProtection is "disabled" or "not_set", secretProtectionCount is 0
 * - If codeSecurity is "disabled" or "not_set", codeSecurityCount is 0
 * - "enabled" or "custom" require licenses
 * SKU filtering (bundled):
 * - bundledCount is 0 only when both SKUs are "disabled"
 * - "not_set" is a paid state for bundled licenses
 */
export function determineLicenseCounts({
  formState,
  forAllRepos,
  forSelectedRepos,
  originalAttachedRepoCount,
}: {
  formState: Pick<QuickSetupFormState, 'applyTo' | 'secretProtection' | 'codeSecurity'>
  forAllRepos: ForAllReposCounts
  forSelectedRepos: ForSelectedReposCounts
  originalAttachedRepoCount?: number
}) {
  const {applyTo, secretProtection, codeSecurity} = formState

  const zeroCounts: LicenseCounts = {secretProtectionCount: 0, codeSecurityCount: 0, bundledCount: 0}

  let repoCount: number
  let baseLicenseCounts: LicenseCounts
  switch (applyTo) {
    case QuickSetupApplyTo.None:
      return {repoCount: 0, ...zeroCounts}
    case QuickSetupApplyTo.All:
      repoCount = forAllRepos.repoCount
      baseLicenseCounts = {
        secretProtectionCount: forAllRepos.licenseUsage.secret_protection?.license_count ?? 0,
        codeSecurityCount: forAllRepos.licenseUsage.code_security?.license_count ?? 0,
        bundledCount: forAllRepos.licenseUsage.bundled?.license_count ?? 0,
      }
      break
    case QuickSetupApplyTo.Selected:
      repoCount = forSelectedRepos.repoCount
      baseLicenseCounts = forSelectedRepos.licenseCounts
      break
    case QuickSetupApplyTo.NotApplicable:
      // License counts aren't displayed for NotApplicable (ReviewStep hides the estimates section)
      return {repoCount: originalAttachedRepoCount ?? 0, ...zeroCounts}
    default: {
      const exhaustiveCheck: never = applyTo
      throw new Error(`Unhandled applyTo case: ${exhaustiveCheck}`)
    }
  }

  // Apply SKU filtering: disabled SKUs don't require licenses
  const filtered = applySkuEnablementFiltering(baseLicenseCounts, {secretProtection, codeSecurity})
  return {repoCount, ...filtered}
}
