import pluralize from 'pluralize'
import {AlertIcon} from '@primer/octicons-react'
import {useAppContext} from '../../contexts/AppContext'
import type {LicenseCounts, OrganizationLicensePayload} from '../../security-products-enablement-types'
import styles from './QuickSetupDialog.module.css'

interface FooterLicenseCountsProps {
  licenseCounts: LicenseCounts
  licenses?: OrganizationLicensePayload
}

/**
 * Displays license counts in dialog footers.
 */
export function FooterLicenseCounts({licenseCounts, licenses}: FooterLicenseCountsProps) {
  const {secretProtectionCount, codeSecurityCount, bundledCount} = licenseCounts
  const {capabilities} = useAppContext()
  const isBundled = capabilities.advancedSecurity.bundled
  const isVolume = !capabilities.advancedSecurity.metered

  const showUnbundledLicenses = !isBundled

  const hasLicenseData = licenses && !licenses.failedToFetchLicenses
  const showVolumeInfo = isVolume && hasLicenseData

  const bundledAvailable = licenses?.bundled?.remainingSeats ?? 0
  const spAvailable = licenses?.secret_protection?.remainingSeats ?? 0
  const csAvailable = licenses?.code_security?.remainingSeats ?? 0

  const bundledWarning = showVolumeInfo && !licenses.bundled?.hasUnlimitedSeats && bundledCount > bundledAvailable
  const spWarning =
    showVolumeInfo && !licenses.secret_protection?.hasUnlimitedSeats && secretProtectionCount > spAvailable
  const csWarning = showVolumeInfo && !licenses.code_security?.hasUnlimitedSeats && codeSecurityCount > csAvailable

  return (
    <div className={styles.licenseCounts}>
      {showUnbundledLicenses ? (
        <>
          <div className="text-small color-fg-muted">
            {spWarning && (
              <span data-testid="license-warning-icon">
                <AlertIcon size={12} className="mr-1 color-fg-attention" aria-label="Warning" />
              </span>
            )}
            {secretProtectionCount} additional Secret Protection {pluralize('license', secretProtectionCount)} required
            {showVolumeInfo && !licenses.secret_protection?.hasUnlimitedSeats && ` • ${spAvailable} available`}
          </div>
          <div className="text-small color-fg-muted">
            {csWarning && (
              <span data-testid="license-warning-icon">
                <AlertIcon size={12} className="mr-1 color-fg-attention" aria-label="Warning" />
              </span>
            )}
            {codeSecurityCount} additional Code Security {pluralize('license', codeSecurityCount)} required
            {showVolumeInfo && !licenses.code_security?.hasUnlimitedSeats && ` • ${csAvailable} available`}
          </div>
        </>
      ) : (
        <div className="text-small color-fg-muted">
          {bundledWarning && (
            <span data-testid="license-warning-icon">
              <AlertIcon size={12} className="mr-1 color-fg-attention" aria-label="Warning" />
            </span>
          )}
          {bundledCount} additional GitHub Advanced Security {pluralize('license', bundledCount)} required
          {showVolumeInfo && !licenses.bundled?.hasUnlimitedSeats && ` • ${bundledAvailable} available`}
        </div>
      )}
    </div>
  )
}
