import {Banner, Link} from '@primer/react'
import pluralize from 'pluralize'
import type {WarningState} from '../../hooks/use-warning-state'
import {skuNames} from './ghas-skus'
import {CONTACT_SALES_URL} from '../../utils/constants'

interface SettingsStepWarningProps {
  warning: WarningState
}

export function SettingsStepWarning({warning}: SettingsStepWarningProps) {
  switch (warning.kind) {
    case 'policy-restricted':
      return (
        <Banner
          variant="warning"
          title={`Modifying ${skuNames(warning.products)} has been blocked by an enterprise policy`}
          hideTitle
          data-testid="settings-step-warning"
          description={`Modifying ${skuNames(warning.products)} has been blocked by an enterprise policy. Continue with free features for all repositories, or cancel and change your selection.`}
        />
      )

    case 'enablement-locked':
      return (
        <Banner
          variant="info"
          title="Enablement locked for new repositories"
          data-testid="settings-step-warning"
          description={`${skuNames(warning.products)} features cannot be enabled on additional repositories due to a billing issue. Configurations for existing repositories can be managed as usual. After resolving the issue, please allow a few minutes for changes to apply.`}
        />
      )

    case 'not-purchased':
      return (
        <Banner
          variant="warning"
          title={`This organization does not have ${skuNames(warning.products)}`}
          hideTitle
          data-testid="settings-step-warning"
          description={
            <>
              This organization does not have {skuNames(warning.products)}, please{' '}
              <Link href={CONTACT_SALES_URL} target="_blank" rel="noopener noreferrer" inline>
                contact sales
              </Link>
              . Private repositories will only have free features enabled.
            </>
          }
        />
      )

    case 'overage':
      return (
        <Banner
          variant="warning"
          title={`Your organization has exceeded its ${skuNames(warning.products)} license limit`}
          data-testid="settings-step-warning"
          description={`You are currently using ${warning.exceededLicenses} more ${pluralize('license', warning.exceededLicenses)} than purchased. Applying this configuration may add further usage. To resolve this, remove ${skuNames(warning.products)} features from some repositories or buy additional licenses.`}
        />
      )

    case 'not-enough-seats':
      return (
        <Banner
          variant="warning"
          title={`${warning.licensesToPurchase} additional ${skuNames(warning.products)} ${pluralize('license', warning.licensesToPurchase)} needed`}
          data-testid="settings-step-warning"
          description={`Applying this configuration requires more licenses than are available. To make changes, remove ${skuNames(warning.products)} features from some repositories or buy additional licenses.`}
        />
      )
  }
}
