import {useMemo} from 'react'
import type {LicenseCounts, Repository} from '../security-products-enablement-types'

interface UseSelectedLicenseCountsOptions {
  selectedRepoIds: Set<number>
  reposById: Map<number, Repository>
}

/**
 * Calculates the net new license counts for selected repositories.
 * Deduplicates committer IDs across all selected repos to return unique counts.
 */
export function useSelectedLicenseCounts({selectedRepoIds, reposById}: UseSelectedLicenseCountsOptions): LicenseCounts {
  return useMemo(() => {
    const secretProtectionCommitterIds = new Set<number>()
    const codeSecurityCommitterIds = new Set<number>()
    const bundledCommitterIds = new Set<number>()

    for (const repoId of selectedRepoIds) {
      const repo = reposById.get(repoId)
      if (!repo) continue

      // Add additional (net new) committer IDs for each SKU
      for (const id of repo.additionalSecretProtectionCommitterIds ?? []) {
        secretProtectionCommitterIds.add(id)
      }

      for (const id of repo.additionalCodeSecurityCommitterIds ?? []) {
        codeSecurityCommitterIds.add(id)
      }

      for (const id of repo.additionalBundledCommitterIds ?? []) {
        bundledCommitterIds.add(id)
      }
    }

    return {
      secretProtectionCount: secretProtectionCommitterIds.size,
      codeSecurityCount: codeSecurityCommitterIds.size,
      bundledCount: bundledCommitterIds.size,
    }
  }, [selectedRepoIds, reposById])
}
