import {ActionMenu, ActionList, Label, Stack, ToggleSwitch} from '@primer/react'
import {SkeletonBox, Blankslate} from '@primer/react/experimental'
import {AlertIcon} from '@primer/octicons-react'
import {
  QuickSetupSettingValue,
  QuickSetupDialogMode,
  QuickSetupDefaultForNewRepos,
} from '../../security-products-enablement-types'
import styles from './SettingsStep.module.css'
import type {
  QuickSetupFormState,
  QuickSetupDialogModeType,
  RepositoryPickerState,
  OrganizationLicensePayload,
} from '../../security-products-enablement-types'
import {useAppContext} from '../../contexts/AppContext'
import {ApplyToSectionRepositoriesTab} from './ApplyTo/ApplyToSectionRepositoriesTab'
import {ApplyToSectionLargeConfig} from './ApplyTo/ApplyToSectionLargeConfig'
import {ApplyToSectionInlinePicker} from './ApplyTo/ApplyToSectionInlinePicker'
import {GHAS_SKUS} from './ghas-skus'
import {SettingsStepWarning} from './SettingsStepWarning'
import type {WarningState} from '../../hooks/use-warning-state'
import {getQuickSetupProductAvailability} from '../../utils/helpers'

const SETTING_LABELS: Record<QuickSetupSettingValue, string> = {
  [QuickSetupSettingValue.Enabled]: 'Enabled',
  [QuickSetupSettingValue.Disabled]: 'Disabled',
  [QuickSetupSettingValue.NotSet]: 'Not set',
  [QuickSetupSettingValue.Custom]: 'Custom',
}

const DEFAULT_FOR_NEW_REPOS_LABELS: Record<QuickSetupDefaultForNewRepos, string> = {
  [QuickSetupDefaultForNewRepos.None]: 'None',
  [QuickSetupDefaultForNewRepos.Public]: 'Public',
  [QuickSetupDefaultForNewRepos.Private]: 'Private and internal',
  [QuickSetupDefaultForNewRepos.All]: 'All',
}

interface EnablementMenuProps {
  label: string
  selectedValue: QuickSetupSettingValue
  onSelect: (value: QuickSetupSettingValue) => void
  includeCustomOption?: boolean
  'aria-labelledby'?: string
  'aria-describedby'?: string
}

function EnablementMenu({
  label,
  selectedValue,
  onSelect,
  includeCustomOption = false,
  'aria-labelledby': ariaLabelledBy,
  'aria-describedby': ariaDescribedBy,
}: EnablementMenuProps) {
  // Base options - always include enabled, disabled, not_set
  const baseValues: QuickSetupSettingValue[] = [
    QuickSetupSettingValue.Enabled,
    QuickSetupSettingValue.Disabled,
    QuickSetupSettingValue.NotSet,
  ]
  // Only include custom if the current value is custom
  const settingValues = includeCustomOption ? [...baseValues, QuickSetupSettingValue.Custom] : baseValues

  return (
    <ActionMenu>
      <ActionMenu.Button aria-labelledby={ariaLabelledBy} aria-describedby={ariaDescribedBy}>
        {SETTING_LABELS[selectedValue]}
      </ActionMenu.Button>
      <ActionMenu.Overlay>
        <ActionList selectionVariant="single" aria-label={label}>
          {settingValues.map(value => (
            <ActionList.Item
              key={value}
              selected={value === selectedValue}
              aria-checked={value === selectedValue}
              onSelect={() => onSelect(value)}
            >
              {SETTING_LABELS[value]}
            </ActionList.Item>
          ))}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

interface SettingsStepProps {
  formState: QuickSetupFormState
  onFormStateChange: (newState: QuickSetupFormState) => void
  isLoading: boolean
  isLoadError: boolean
  dialogMode?: QuickSetupDialogModeType
  originalConfig?: {
    secret_protection: QuickSetupSettingValue
    code_security: QuickSetupSettingValue
    dependabot: QuickSetupSettingValue
  } | null
  // Repository picker state for selected repositories subfield (optional - only used by FirstConfigSetupPage)
  repositoryPicker?: RepositoryPickerState
  onSelectionChange?: (ids: Set<number>) => void
  // When true, security feature settings are displayed as read-only labels (e.g. for enterprise configs and GHR)
  settingsReadOnly?: boolean
  // License data for banners
  licenses?: OrganizationLicensePayload
  warning?: WarningState | null
}

function ReadOnlySettingLabel({value, label}: {value: QuickSetupSettingValue; label: string}) {
  return (
    <span className={styles.readOnlyLabel}>
      <span className="sr-only">{label}: </span>
      {SETTING_LABELS[value]}
    </span>
  )
}

export function SettingsStep({
  formState,
  onFormStateChange,
  isLoading = false,
  isLoadError = false,
  dialogMode = QuickSetupDialogMode.NEW,
  originalConfig = null,
  repositoryPicker,
  onSelectionChange,
  settingsReadOnly = false,
  licenses,
  warning,
}: SettingsStepProps) {
  const {
    capabilities: {advancedSecurity, quickSetupHasDetailedDescription},
    securityProducts,
  } = useAppContext()
  const updateField = (updates: Partial<QuickSetupFormState>) => {
    onFormStateChange({...formState, ...updates})
  }
  const secretProtectionName = advancedSecurity.bundled
    ? GHAS_SKUS.secretProtection.bundledName
    : GHAS_SKUS.secretProtection.name
  const codeSecurityName = advancedSecurity.bundled ? GHAS_SKUS.codeSecurity.bundledName : GHAS_SKUS.codeSecurity.name
  const {
    secretProtection: showSecretProtection,
    codeSecurity: showCodeSecurity,
    dependabot: showDependabot,
  } = getQuickSetupProductAvailability(securityProducts)
  const showDetailedDescriptions = quickSetupHasDetailedDescription

  // Determine which Apply To section variant to render
  const renderInlinePicker = repositoryPicker && onSelectionChange
  // True when configuration is attached to >500 repos (not about org size)
  const isLargeConfig = formState.isNotApplicable

  // Check if a setting should show the Custom option in dropdown
  // (only when the original config value was custom)
  const shouldShowCustomOption = (setting: 'secret_protection' | 'code_security' | 'dependabot'): boolean => {
    if (dialogMode !== QuickSetupDialogMode.EDIT || !originalConfig) return false
    return originalConfig[setting] === 'custom'
  }

  if (isLoadError) {
    return (
      <div>
        <Blankslate>
          <Blankslate.Visual>
            <AlertIcon size={24} className="color-fg-danger" />
          </Blankslate.Visual>
          <Blankslate.Heading>We couldn&apos;t load the configuration</Blankslate.Heading>
          <Blankslate.Description>Try again, or if the problem persists, contact support.</Blankslate.Description>
        </Blankslate>
      </div>
    )
  }

  if (isLoading) {
    return (
      <Stack gap="normal" aria-busy="true">
        <div className={styles.settingsCard}>
          <SkeletonBox height="200px" />
        </div>
        <div className={styles.settingsCard}>
          <SkeletonBox height="100px" />
        </div>
      </Stack>
    )
  }

  return (
    <Stack gap="normal">
      {warning && <SettingsStepWarning warning={warning} />}

      {/* Apply settings */}
      <div className={styles.settingsCard}>
        <Stack direction="vertical" gap="none">
          {/* Render appropriate Apply To section based on context */}
          {renderInlinePicker ? (
            <ApplyToSectionInlinePicker
              onApplyToChange={value => updateField({applyTo: value})}
              repositoryPicker={repositoryPicker}
              selectedRepoIds={formState.selectedRepoIds}
              onSelectionChange={onSelectionChange}
              formState={formState}
              licenses={licenses}
            />
          ) : isLargeConfig ? (
            <ApplyToSectionLargeConfig
              applyTo={formState.applyTo}
              onApplyToChange={value => updateField({applyTo: value})}
            />
          ) : (
            <ApplyToSectionRepositoriesTab
              applyTo={formState.applyTo}
              onApplyToChange={value => updateField({applyTo: value})}
            />
          )}

          <div className={styles.defaultForNewReposRow}>
            <div className={styles.settingLabel}>
              <div id="default-for-new-repos-label">Default for new repositories</div>
            </div>
            <ActionMenu>
              <ActionMenu.Button aria-labelledby="default-for-new-repos-label">
                {DEFAULT_FOR_NEW_REPOS_LABELS[formState.defaultForNewRepos]}
              </ActionMenu.Button>
              <ActionMenu.Overlay>
                <ActionList selectionVariant="single">
                  {(Object.keys(DEFAULT_FOR_NEW_REPOS_LABELS) as QuickSetupDefaultForNewRepos[]).map(value => (
                    <ActionList.Item
                      key={value}
                      selected={value === formState.defaultForNewRepos}
                      aria-checked={value === formState.defaultForNewRepos}
                      onSelect={() => updateField({defaultForNewRepos: value})}
                    >
                      {DEFAULT_FOR_NEW_REPOS_LABELS[value]}
                    </ActionList.Item>
                  ))}
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          </div>

          <div className={styles.repoOwnerModifyRow}>
            <div className={styles.settingLabel}>
              <div id="allow-repo-owners-label">Allow repository owners to modify features</div>
            </div>
            <ToggleSwitch
              aria-labelledby="allow-repo-owners-label"
              checked={formState.repoOwnerCanModify}
              onClick={() => updateField({repoOwnerCanModify: !formState.repoOwnerCanModify})}
            />
          </div>
        </Stack>
      </div>

      {/* Security features */}
      <div className={styles.settingsCard}>
        <Stack direction="vertical" gap="none">
          {showSecretProtection && (
            <div className={styles.productRow}>
              <div className={styles.settingLabel}>
                <div className="d-flex flex-items-center flex-wrap gap-1">
                  <span id="secret-protection-label">{secretProtectionName}</span>
                  {advancedSecurity.bundled && <Label size="small">GitHub Advanced Security</Label>}
                </div>
                <div id="secret-protection-desc" className={styles.settingDescription}>
                  {showDetailedDescriptions
                    ? 'Receive alerts for and block secret leaks, validate secrets and scan with AI. '
                    : 'Includes alerts for detected secrets. '}
                  {advancedSecurity.metered &&
                    (advancedSecurity.bundled ? (
                      <strong>{GHAS_SKUS.bundled.perActiveCommitter}</strong>
                    ) : (
                      <strong>{GHAS_SKUS.secretProtection.perActiveCommitter}</strong>
                    ))}
                </div>
              </div>
              {settingsReadOnly ? (
                <ReadOnlySettingLabel value={formState.secretProtection} label={secretProtectionName} />
              ) : (
                <EnablementMenu
                  label={secretProtectionName}
                  selectedValue={formState.secretProtection}
                  onSelect={value => updateField({secretProtection: value})}
                  includeCustomOption={shouldShowCustomOption('secret_protection')}
                  aria-labelledby="secret-protection-label"
                  aria-describedby="secret-protection-desc"
                />
              )}
            </div>
          )}

          {showCodeSecurity && (
            <div className={styles.productRow}>
              <div className={styles.settingLabel}>
                <div className="d-flex flex-items-center flex-wrap gap-1">
                  <span id="code-security-label">{codeSecurityName}</span>
                  {advancedSecurity.bundled && <Label size="small">GitHub Advanced Security</Label>}
                </div>
                <div id="code-security-desc" className={styles.settingDescription}>
                  {showDetailedDescriptions
                    ? 'Receive alerts for vulnerabilities, coding errors, and advanced dependency management. '
                    : 'Includes alerts for code vulnerabilities. '}
                  {advancedSecurity.metered &&
                    (advancedSecurity.bundled ? (
                      <strong>{GHAS_SKUS.bundled.perActiveCommitter}</strong>
                    ) : (
                      <strong>{GHAS_SKUS.codeSecurity.perActiveCommitter}</strong>
                    ))}
                </div>
              </div>
              {settingsReadOnly ? (
                <ReadOnlySettingLabel value={formState.codeSecurity} label={codeSecurityName} />
              ) : (
                <EnablementMenu
                  label={codeSecurityName}
                  selectedValue={formState.codeSecurity}
                  onSelect={value => updateField({codeSecurity: value})}
                  includeCustomOption={shouldShowCustomOption('code_security')}
                  aria-labelledby="code-security-label"
                  aria-describedby="code-security-desc"
                />
              )}
            </div>
          )}

          {showDependabot && (
            <div className={styles.productRow}>
              <div className={styles.settingLabel}>
                <div id="dependabot-label">Dependabot</div>
                <div id="dependabot-desc" className={styles.settingDescription}>
                  {showDetailedDescriptions
                    ? 'Receive alerts for vulnerable dependencies with automated update pull requests. '
                    : 'Includes alerts for vulnerable dependencies. '}
                  {advancedSecurity.metered && <span style={{fontWeight: 'bold'}}>Free.</span>}
                </div>
              </div>
              {settingsReadOnly ? (
                <ReadOnlySettingLabel value={formState.dependabot} label="Dependabot" />
              ) : (
                <EnablementMenu
                  label="Dependabot"
                  selectedValue={formState.dependabot}
                  onSelect={value => updateField({dependabot: value})}
                  includeCustomOption={shouldShowCustomOption('dependabot')}
                  aria-labelledby="dependabot-label"
                  aria-describedby="dependabot-desc"
                />
              )}
            </div>
          )}
        </Stack>
      </div>
    </Stack>
  )
}
