import {Banner, Flash, Link} from '@primer/react'
import {StartTrialDialog} from '@github-ui/licensing-advanced-security-overview/components/StartTrialDialog'
import type {SelfServeTrialInfo} from '@github-ui/licensing-advanced-security-overview/types/self-serve-trial-info'
import {NavigationContextProvider} from '@github-ui/licensing-common/contexts/NavigationContext'
import {useStartTrialDialog} from '../../hooks/use-start-trial-dialog'
import type {UpsellType} from '../../security-products-enablement-types'

import {CONTACT_SALES_URL} from '../../utils/constants'

export interface UpsellBannerProps {
  upsellType: UpsellType
  selfServeTrialInfo?: SelfServeTrialInfo
  onDismiss: () => void
}

export function UpsellBanner({upsellType, selfServeTrialInfo, onDismiss}: UpsellBannerProps) {
  // Volume customers who haven't upgraded to Advanced Security see a "Contact sales" banner
  if (upsellType === 'volume_contact_sales') {
    return (
      <Banner
        title="Stop vulnerabilities before they reach production"
        description="Contact sales to upgrade to Advanced Security and protect your code, secrets and dependencies."
        variant="upsell"
        onDismiss={onDismiss}
        primaryAction={
          <Banner.PrimaryAction as={Link} href={CONTACT_SALES_URL}>
            Contact sales
          </Banner.PrimaryAction>
        }
      />
    )
  }

  // For trial banner, we need selfServeTrialInfo
  if (upsellType !== 'trial' || !selfServeTrialInfo) {
    return null
  }

  return <TrialUpsellBanner selfServeTrialInfo={selfServeTrialInfo} onDismiss={onDismiss} />
}

function TrialUpsellBanner({
  selfServeTrialInfo,
  onDismiss,
}: {
  selfServeTrialInfo: SelfServeTrialInfo
  onDismiss: () => void
}) {
  const {
    showDialog,
    isStartingTrial,
    errorMessage,
    enterpriseSlug,
    ghasFeaturesUrl,
    openDialog,
    closeDialog,
    confirmStart,
  } = useStartTrialDialog({selfServeTrialInfo})

  return (
    <>
      {errorMessage && (
        <Flash variant="danger" className="mb-2">
          {errorMessage}
        </Flash>
      )}
      <Banner
        title="Enable GitHub Advanced Security"
        hideTitle
        description={`Enable GitHub Advanced Security for your enterprise now — the first ${selfServeTrialInfo.trialDays} days are on us.`}
        variant="upsell"
        onDismiss={onDismiss}
        primaryAction={
          <Banner.PrimaryAction onClick={openDialog}>
            Try free for {selfServeTrialInfo.trialDays} days
          </Banner.PrimaryAction>
        }
      />

      {showDialog && (
        <NavigationContextProvider slug={enterpriseSlug} enterpriseContactUrl="">
          <StartTrialDialog
            onClose={closeDialog}
            onConfirmStart={confirmStart}
            isStartingTrial={isStartingTrial}
            selfServeTrialInfo={selfServeTrialInfo}
            ghasFeaturesUrl={ghasFeaturesUrl}
          />
        </NavigationContextProvider>
      )}
    </>
  )
}
