import {useState, useCallback} from 'react'
import {startTrial} from '@github-ui/licensing-advanced-security-overview/services/trials'
import type {SelfServeTrialInfo} from '@github-ui/licensing-advanced-security-overview/types/self-serve-trial-info'
import {
  orgOnboardingAdvancedSecurityPath,
  businessLicensingPath,
  settingsEnterpriseAdvancedSecurityPath,
} from '@github-ui/paths'
import {useAppContext} from '../contexts/AppContext'

export interface UseStartTrialDialogOptions {
  selfServeTrialInfo?: SelfServeTrialInfo
}

export interface UseStartTrialDialogReturn {
  showDialog: boolean
  isStartingTrial: boolean
  errorMessage: string | null
  enterpriseSlug: string
  advancedSecuritySettingsPath: string
  ghasFeaturesUrl: string
  openDialog: () => void
  closeDialog: () => void
  confirmStart: () => Promise<void>
}

export function useStartTrialDialog({selfServeTrialInfo}: UseStartTrialDialogOptions): UseStartTrialDialogReturn {
  const {enterprise, docsUrls} = useAppContext()
  const [showDialog, setShowDialog] = useState(false)
  const [isStartingTrial, setIsStartingTrial] = useState(false)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)

  const enterpriseSlug = enterprise?.slug ?? ''
  const advancedSecuritySettingsPath = settingsEnterpriseAdvancedSecurityPath({enterprise: enterpriseSlug})
  const ghasFeaturesUrl = docsUrls.aboutGHAS

  const openDialog = useCallback(() => {
    setErrorMessage(null)
    setShowDialog(true)
  }, [])

  const closeDialog = useCallback(() => {
    setShowDialog(false)
    setIsStartingTrial(false)
    setErrorMessage(null)
  }, [])

  const selfServeInfoOrganizationToOnboard = selfServeTrialInfo?.organizationToOnboard
  const confirmStart = useCallback(async () => {
    setIsStartingTrial(true)
    setErrorMessage(null)

    try {
      await startTrial(advancedSecuritySettingsPath)
      // Redirect to organization onboarding if available, otherwise go to licensing page
      if (selfServeInfoOrganizationToOnboard != null) {
        window.location.href = orgOnboardingAdvancedSecurityPath({org: selfServeInfoOrganizationToOnboard})
      } else {
        window.location.href = businessLicensingPath({businessSlug: enterpriseSlug})
      }
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : 'Sorry, we were unable to start your free trial.')
    } finally {
      setShowDialog(false)
      setIsStartingTrial(false)
    }
  }, [advancedSecuritySettingsPath, enterpriseSlug, selfServeInfoOrganizationToOnboard])

  return {
    showDialog,
    isStartingTrial,
    errorMessage,
    enterpriseSlug,
    advancedSecuritySettingsPath,
    ghasFeaturesUrl,
    openDialog,
    closeDialog,
    confirmStart,
  }
}
