import type React from 'react'
import capitalize from 'lodash-es/capitalize'
import pluralize from 'pluralize'
import {Link as PrimerLink, IconButton, Spinner} from '@primer/react'
import {Link} from '@github-ui/react-core/link'
import {QuickSetupDialogMode} from '../../security-products-enablement-types'
import {
  RenderContext,
  type MiniSecurityConfiguration,
  type ChangesInProgress,
  type QuickSetupDialogModeType,
} from '../../security-products-enablement-types'
import {
  settingsBusinessSecurityAnalysisConfigurationsEditPath,
  settingsBusinessSecurityAnalysisConfigurationsViewPath,
  settingsOrgSecurityConfigurationsEditPath,
  settingsOrgSecurityConfigurationsViewPath,
  settingsOrgSecurityProductsPath,
  settingsUserSecurityConfigurationsEditPath,
  settingsUserSecurityConfigurationsViewPath,
} from '@github-ui/paths'
import {useAppContext} from '../../contexts/AppContext'
import ApplyToButton from './ApplyToButton'
import RowLabel from '../RowLabel'
import {PencilIcon, AlertIcon, InfoIcon, ShieldLockIcon} from '@primer/octicons-react'
import {getEscapedFilterValue} from '@github-ui/filter-core'

import styles from './Row.module.css'

export interface OpenQuickSetupOptions {
  dialogMode: QuickSetupDialogModeType
  settingsReadOnly: boolean
  configurationId?: number
  originalAttachedRepoCount?: number
  failedReposCount?: number
}

interface SecurityConfigurationRowProps {
  configuration: MiniSecurityConfiguration
  isLast: boolean
  isFirst?: boolean
  configurationType: string
  onOpenQuickSetup?: (options: OpenQuickSetupOptions) => void
  changesInProgress?: ChangesInProgress
  setChangesInProgress?: React.Dispatch<React.SetStateAction<ChangesInProgress>>
}

const SecurityConfigurationRow: React.FC<SecurityConfigurationRowProps> = ({
  configuration,
  isLast,
  isFirst = false,
  configurationType,
  onOpenQuickSetup,
  changesInProgress,
  setChangesInProgress,
}) => {
  const {
    organization,
    enterprise,
    capabilities: {advancedSecurity},
    renderContext,
  } = useAppContext()
  const {
    default_for_new_private_repos,
    default_for_new_public_repos,
    id,
    name,
    enable_ghas,
    enforcement,
    description,
    repositories_count,
    code_security_sku_enabled,
    secret_protection_sku_enabled,
    failed_repos_count,
    removed_repos_count,
  } = configuration

  const isOrgQuickSetupEnabled = renderContext === RenderContext.Organization
  const isApplying =
    changesInProgress?.inProgress &&
    changesInProgress.type === 'applying_configuration' &&
    changesInProgress.configurationId === id

  const applyingRepoCount = changesInProgress?.repositoryCount ?? 0

  const linkPath = () => {
    switch (renderContext) {
      case RenderContext.Enterprise:
        return configurationType === 'githubRecommended'
          ? settingsBusinessSecurityAnalysisConfigurationsViewPath({business: enterprise!.slug, id})
          : settingsBusinessSecurityAnalysisConfigurationsEditPath({business: enterprise!.slug, id})
      case RenderContext.Organization:
        return configurationType === 'githubRecommended' || configurationType === 'enterprise'
          ? settingsOrgSecurityConfigurationsViewPath({org: organization, id})
          : settingsOrgSecurityConfigurationsEditPath({org: organization, id})
      case RenderContext.User:
        return configurationType === 'githubRecommended'
          ? settingsUserSecurityConfigurationsViewPath({id})
          : settingsUserSecurityConfigurationsEditPath({id})
      default:
        return ''
    }
  }

  let boxClassNames = `border-x border-bottom tmp-py-3 tmp-px-3`
  if (isFirst) boxClassNames = `${boxClassNames} rounded-top-2 border-top`
  if (isLast) boxClassNames = `${boxClassNames} rounded-bottom-2`

  const getDefaultText = () => {
    if (default_for_new_private_repos && default_for_new_public_repos) {
      return 'Default for all new repositories.'
    } else if (default_for_new_private_repos) {
      return 'Default for new private and internal repositories.'
    } else {
      return 'Default for new public repositories.'
    }
  }

  const configurationNameFilterURL = () => {
    const escapedValue = getEscapedFilterValue(configuration.name) || ''
    const searchQuery = `configuration:${escapedValue}`
    return settingsOrgSecurityProductsPath({org: organization, q: searchQuery})
  }

  const configurationStatusFilterURL = (status: 'failed' | 'removed') => {
    const escapedValue = getEscapedFilterValue(configuration.name) || ''
    const statusFilter = status === 'removed' ? 'removed,removed_by_enterprise' : status
    const searchQuery = `configuration:${escapedValue} config-status:${statusFilter}`
    return settingsOrgSecurityProductsPath({org: organization, q: searchQuery})
  }

  const repoCounts = () => {
    if (renderContext === RenderContext.Enterprise) {
      // We do not support linking to repo counts on the Enterprise page:
      return pluralize('repository', repositories_count, true)
    } else if (renderContext === RenderContext.Organization) {
      // We are setting reloadDocument=true to trigger a turbo nav since we don't support react routing
      // for the filter string:
      return (
        <PrimerLink as={Link} to={configurationNameFilterURL()} reloadDocument className="color-fg-muted">
          {pluralize('repository', repositories_count, true)}
        </PrimerLink>
      )
    } else {
      return ''
    }
  }

  const ghasPill = advancedSecurity.purchased && advancedSecurity.bundled && enable_ghas
  const codeSecurityPill = !advancedSecurity.bundled && code_security_sku_enabled
  const secretProtectionPill = !advancedSecurity.bundled && secret_protection_sku_enabled

  const renderConfigurationWarnings = () => {
    const indicators = []

    if (failed_repos_count && failed_repos_count > 0) {
      indicators.push(
        <PrimerLink
          key="failed"
          as={Link}
          to={configurationStatusFilterURL('failed')}
          reloadDocument
          className={`${styles.StatusIndicator} ${styles.StatusIndicator_failed}`}
          data-testid={`configuration-${id}-failed-repos`}
        >
          <AlertIcon size={16} />
          <span>{failed_repos_count} failed to apply</span>
        </PrimerLink>,
      )
    }

    if (removed_repos_count && removed_repos_count > 0) {
      indicators.push(
        <PrimerLink
          key="removed"
          as={Link}
          to={configurationStatusFilterURL('removed')}
          reloadDocument
          className={`${styles.StatusIndicator} ${styles.StatusIndicator_removed}`}
          data-testid={`configuration-${id}-removed-repos`}
        >
          <InfoIcon size={16} />
          <span>{removed_repos_count} removed</span>
        </PrimerLink>,
      )
    }

    return indicators.length > 0 ? (
      <div className="d-flex gap-3 mt-1" role="status" aria-live="polite" aria-atomic="true">
        {indicators}
      </div>
    ) : null
  }

  const renderQuickSetupApplicationState = (openQuickSetup: (options: OpenQuickSetupOptions) => void) => (
    <>
      <div className="d-flex flex-items-center gap-2">
        {enforcement === 'enforced' && (
          <ShieldLockIcon size={16} className="color-fg-muted" data-testid={`configuration-${id}-enforced-icon`} />
        )}
        <div className="f6 color-fg-muted" data-testid={`configuration-${id}-repositories-count`}>
          {repoCounts()}
        </div>
      </div>
      <IconButton
        icon={PencilIcon}
        aria-label={`Edit ${name}`}
        className={styles.IconButton}
        onClick={() =>
          openQuickSetup({
            dialogMode: QuickSetupDialogMode.EDIT,
            configurationId: id,
            settingsReadOnly: configurationType === 'enterprise' || configurationType === 'githubRecommended',
            originalAttachedRepoCount: repositories_count,
            failedReposCount: failed_repos_count,
          })
        }
      />
    </>
  )

  const renderDefaultApplicationState = () => (
    <>
      <div className="f6 tmp-m-3 color-fg-muted flex-2" data-testid={`configuration-${id}-repositories-count`}>
        {repoCounts()}
      </div>
      <ApplyToButton configuration={configuration} setChangesInProgress={setChangesInProgress} />
      <IconButton
        as={PrimerLink}
        href={linkPath()}
        icon={PencilIcon}
        aria-label={`Edit ${name}`}
        className={styles.IconButton}
      />
    </>
  )

  return (
    <div className={boxClassNames} data-testid={`configuration-${id}`}>
      <div className="d-flex flex-items-center flex-wrap">
        <div className="text-bold flex-1" style={{maxWidth: '100%'}}>
          <div className="d-flex flex-wrap mr-2">
            <PrimerLink
              as={Link}
              to={linkPath()}
              data-testid={`configuration-${id}-name`}
              className={styles.PrimerLink}
            >
              {name.length > 0 ? name : 'unnamed security configuration'}
            </PrimerLink>
            <div className="d-flex gap-1 flex-wrap">
              {ghasPill && <RowLabel text="GitHub Advanced Security" />}
              {secretProtectionPill && <RowLabel text="Secret Protection" />}
              {codeSecurityPill && <RowLabel text="Code Security" />}
              {enforcement === 'enforced' && !isOrgQuickSetupEnabled && <RowLabel text={capitalize(enforcement)} />}
            </div>
          </div>

          <div className="f6 color-fg-muted text-normal" data-testid={`configuration-${id}-description`}>
            {description}{' '}
            {(default_for_new_private_repos || default_for_new_public_repos) && (
              <span className="text-bold">{getDefaultText()}</span>
            )}
          </div>
          {isOrgQuickSetupEnabled && renderConfigurationWarnings()}
        </div>
        <div className="d-flex flex-items-center" style={{marginLeft: 'auto'}}>
          {isApplying ? (
            <div
              className={`${styles.StatusIndicator} ${styles.StatusIndicator_applying}`}
              data-testid={`configuration-${id}-applying`}
              role="status"
              aria-live="polite"
            >
              <Spinner size="small" srText="Loading" />
              <span className="ml-2">Applying to {pluralize('repository', applyingRepoCount, true)}...</span>
            </div>
          ) : isOrgQuickSetupEnabled && onOpenQuickSetup ? (
            renderQuickSetupApplicationState(onOpenQuickSetup)
          ) : (
            renderDefaultApplicationState()
          )}
        </div>
      </div>
    </div>
  )
}

export default SecurityConfigurationRow
