import {Button, Stack} from '@primer/react'
import {AlertIcon} from '@primer/octicons-react'
import {SkeletonBox} from '@primer/react/experimental'
import pluralize from 'pluralize'
import {useAppContext} from '../../contexts/AppContext'
import type {LicenseCounts, OrganizationLicensePayload} from '../../security-products-enablement-types'
import type {WarningState} from '../../hooks/use-warning-state'
import {ReviewStepWarning} from './ReviewStepWarning'
import styles from './ReviewStep.module.css'
import {GHAS_SKUS} from './ghas-skus'

interface ReviewStepLicenseSectionProps {
  licenseCounts: LicenseCounts
  licenses?: OrganizationLicensePayload
  warning?: WarningState | null
  isLoadingLicenses: boolean
  isLicensesError: boolean
  onRetryLicenses?: () => void
}

export function ReviewStepLicenseSection({
  licenseCounts,
  licenses,
  warning,
  isLoadingLicenses,
  isLicensesError,
  onRetryLicenses,
}: ReviewStepLicenseSectionProps) {
  const {secretProtectionCount, codeSecurityCount, bundledCount} = licenseCounts
  const {
    capabilities: {advancedSecurity},
  } = useAppContext()

  const isBundled = advancedSecurity.bundled
  const isMetered = advancedSecurity.metered
  const isVolume = !isMetered

  const hasLicenseData = licenses && !licenses.failedToFetchLicenses

  const bundledAvailable = licenses?.bundled?.remainingSeats ?? 0
  const spAvailable = licenses?.secret_protection?.remainingSeats ?? 0
  const csAvailable = licenses?.code_security?.remainingSeats ?? 0

  const bundledWarning =
    isVolume && !!hasLicenseData && !licenses.bundled?.hasUnlimitedSeats && bundledCount > bundledAvailable
  const spWarning =
    isVolume &&
    !!hasLicenseData &&
    !licenses.secret_protection?.hasUnlimitedSeats &&
    secretProtectionCount > spAvailable
  const csWarning =
    isVolume && !!hasLicenseData && !licenses.code_security?.hasUnlimitedSeats && codeSecurityCount > csAvailable

  if (isLoadingLicenses) {
    return (
      <Stack direction="vertical" gap="condensed">
        <SkeletonBox height="32px" width="100%" />
        <SkeletonBox height="24px" width="280px" />
        <SkeletonBox height="24px" width="240px" />
      </Stack>
    )
  }

  if (isLicensesError) {
    return (
      <div className={styles.licenseErrorContainer}>
        <AlertIcon size={24} className="color-fg-danger" />
        <div className="color-fg-danger">Failed to load license estimates</div>
        {onRetryLicenses && (
          <Button size="small" variant="invisible" onClick={onRetryLicenses}>
            Try again
          </Button>
        )}
      </div>
    )
  }

  const renderAvailableCount = (available: number, hasWarning: boolean, hasUnlimitedSeats?: boolean) => {
    if (!isVolume || !hasLicenseData || hasUnlimitedSeats) return null
    return (
      <span className="color-fg-muted">
        {hasWarning && <AlertIcon size={12} className="mr-1 color-fg-attention" aria-label="Warning" />}
        {available} {pluralize('license', available)} available
      </span>
    )
  }

  return (
    <>
      <p className={styles.helperText}>
        Based on active committers to private repositories within the last 90 days.
        {isMetered && ' Standard bill rate may not apply if a coupon or discount is available.'}
      </p>
      {isBundled ? (
        <div className={styles.licenseRow}>
          <span>
            {bundledCount} GitHub Advanced Security {pluralize('license', bundledCount)}
          </span>
          {isMetered ? (
            <span>{GHAS_SKUS.bundled.perMonth}</span>
          ) : (
            renderAvailableCount(bundledAvailable, bundledWarning, licenses?.bundled?.hasUnlimitedSeats)
          )}
        </div>
      ) : (
        <>
          <div className={styles.licenseRow}>
            <span>
              {secretProtectionCount} Secret Protection {pluralize('license', secretProtectionCount)}
            </span>
            {isMetered ? (
              <span>{GHAS_SKUS.secretProtection.perMonth}</span>
            ) : (
              renderAvailableCount(spAvailable, spWarning, licenses?.secret_protection?.hasUnlimitedSeats)
            )}
          </div>
          <div className={styles.licenseRow}>
            <span>
              {codeSecurityCount} Code Security {pluralize('license', codeSecurityCount)}
            </span>
            {isMetered ? (
              <span>{GHAS_SKUS.codeSecurity.perMonth}</span>
            ) : (
              renderAvailableCount(csAvailable, csWarning, licenses?.code_security?.hasUnlimitedSeats)
            )}
          </div>
        </>
      )}
      {warning && <ReviewStepWarning warning={warning} />}
    </>
  )
}
