/**
 * Client-side reducer for security configuration settings.
 *
 * Enforces five rules that govern how feature states, SKU toggles, and
 * hierarchy constraints interact. The server validates invariants at save
 * time (see FeatureValidator in the github/github monolith); this reducer
 * enforces them at edit time so the user never submits an invalid state.
 * These two implementations must stay in sync — if they diverge, the client
 * will allow states the server rejects (or vice versa), causing silent data
 * loss or confusing validation errors on save.
 *
 * ── Rules ──
 *
 *   Rule 1 – Parent → child clamp: a child's enablement level cannot exceed
 *            its parent's. Ordering: disabled < not_set < enabled.
 *            Clamps all descendants breadth-first (parents resolved before
 *            children).
 *
 *   Rule 2 – Child → parent pull-up: same invariant as Rule 1, enforced from
 *            the child direction. Walks the full ancestor chain to the root.
 *
 *   Rule 3 – SKU → feature clamp: paid features cannot be enabled without
 *            their SKU toggle. Bundled configs use enableGHAS; unbundled
 *            configs use per-SKU booleans (enableCodeSecurity,
 *            enableSecretProtection). Each feature's `skuPolicy` determines
 *            its new state when a SKU toggle changes:
 *              • enable_on_sku    — force-enable when SKU is on
 *              • preserve_on_sku  — keep existing Enabled; otherwise NotSet
 *              • recommend_on_sku — enable only if server-flagged as recommended
 *            After computing the policy result, the value is clamped to the
 *            feature's parent state (hierarchy-order traversal ensures parents
 *            are resolved first).
 *
 *   Rule 4 – Feature → SKU pull-up: when a user directly enables a paid
 *            feature, auto-enable its billing toggle so the save won't be
 *            rejected by Rule 3's server-side validation.
 *
 *   Rule 5 – Options preservation: rules never modify feature options
 *            (e.g. delegated bypass reviewers, code scanning runner config).
 *            Options are only written when explicitly supplied in the action.
 *
 * ── Non-recursive guarantee ──
 *
 *   Each rule fires only from its stated trigger — never from state changes
 *   produced by another rule. Rules 1, 2, and 3 change feature states but
 *   never trigger Rule 4; Rule 4 fires only on direct user edits.
 */

import {
  SettingValue,
  type SecurityConfigurationSettings,
  type SecurityFeature,
  type SecuritySettingOptionsTypes,
} from '../security-products-enablement-types'
import {type FeatureRule, type Sku, featureTree} from './feature-tree'

/** Action dispatched when a SKU billing toggle changes (Rule 3 / Rule 4). */
type SkuAction = {type: 'SKU'; sku: Sku; value: SettingValue}

/** Action dispatched when a user toggles a single feature (Rules 1, 2, 4). */
type FeatureAction = {
  type: 'FEATURE'
  /** The feature being toggled. */
  setting: SecurityFeature
  /** The new enablement level for the feature. */
  value: SettingValue
  /** When set, auto-enables this billing toggle if the feature is turned on (Rule 4). */
  sku?: Sku
  /** Sub-setting options to attach. */
  options?: SecuritySettingOptionsTypes
}
type SettingsAction = SkuAction | FeatureAction

/** Maps a SettingValue mode to the per-SKU billing toggle value. */
const modeToToggle: Record<SettingValue, boolean | null> = {
  [SettingValue.Enabled]: true,
  [SettingValue.Disabled]: false,
  [SettingValue.NotSet]: null,
}

/**
 * Enforce the hierarchy invariant: a child feature can never be in a more
 * permissive state than its parent. If the parent is Disabled, the child
 * must be Disabled. If the parent is NotSet, an Enabled child is clamped
 * down to NotSet.
 */
function clampToParent(value: SettingValue, parentValue: SettingValue): SettingValue {
  if (parentValue === SettingValue.Disabled) {
    return SettingValue.Disabled
  } else if (parentValue === SettingValue.NotSet && value === SettingValue.Enabled) {
    return SettingValue.NotSet
  } else {
    return value
  }
}

/**
 * Breadth-first clamp of all descendants of `root` so no child exceeds its parent's
 * permissiveness.  Because children are visited in breadth-first order, every
 * parent is resolved before its children.
 */
function clampDescendants(root: SecurityFeature, settings: SecurityConfigurationSettings): void {
  for (const [descendant, parent] of featureTree.descendants(root)) {
    settings[descendant] = clampToParent(settings[descendant], settings[parent])
  }
}

/**
 * Set the billing flag for the target.
 *
 * For bundled_ghas: sets enableGHAS (true/false). The per-SKU toggles are not
 * used in the bundled UI.
 * For a single SKU: sets the per-SKU toggle (enableCodeSecurity or
 * enableSecretProtection) to true, false, or null (not set).
 */
function setBillingToggle(sku: Sku, value: SettingValue, settings: SecurityConfigurationSettings): void {
  if (sku === 'bundled_ghas') {
    // The bundled GHAS toggle only controls enableGHAS (true/false).
    // NotSet is not supported
    if (value !== SettingValue.NotSet) {
      settings.enableGHAS = value === SettingValue.Enabled
    }
  } else {
    // Per-SKU toggle: Enabled → true, Disabled → false, NotSet → null
    const toggle = modeToToggle[value]
    switch (sku) {
      case 'code_security':
        settings.enableCodeSecurity = toggle
        break
      case 'secret_protection':
        settings.enableSecretProtection = toggle
        break
      default: {
        const _exhaustive: never = sku
        throw new Error(`Unknown SKU: ${_exhaustive}`)
      }
    }
  }
}

/**
 * Determine the desired value for a single feature based on its skuPolicy.
 *
 * The SKU's new value determines the behaviour:
 *   Enabled  → apply the feature's skuPolicy
 *   Disabled → disable all features in the SKU
 *   NotSet   → apply the feature's skuPolicy
 */
function resolveSkuPolicy(
  rule: FeatureRule,
  skuValue: SettingValue,
  state: SecurityConfigurationSettings,
): SettingValue {
  // SKU on → apply the feature's policy to decide the initial state
  if (skuValue === SettingValue.Enabled) {
    switch (rule.skuPolicy) {
      case 'enable_on_sku':
        // Always turn on with the SKU (e.g. secret scanning)
        return SettingValue.Enabled
      case 'preserve_on_sku':
        // Keep the user's existing enabled choice; otherwise start as not set.
        return state[rule.feature] === SettingValue.Enabled ? SettingValue.Enabled : SettingValue.NotSet
      case 'recommend_on_sku':
        // Only auto-enable if the server flagged this feature as recommended
        // for this particular configuration (e.g. validity checks).
        return rule.recommendedFlag && state[rule.recommendedFlag] ? SettingValue.Enabled : SettingValue.NotSet
      case null:
        return SettingValue.NotSet
      default: {
        const _exhaustive: never = rule.skuPolicy
        throw new Error(`Unknown skuPolicy: ${_exhaustive}`)
      }
    }
  }

  // SKU off → disable everything in this SKU
  if (skuValue === SettingValue.Disabled) {
    return SettingValue.Disabled
  }

  // SKU set to not set (only possible in the unbundled toggle UI) —
  // apply the feature's policy: enable_on_sku and recommend_on_sku
  // go back to not set; all others go to disabled.
  if (rule.skuPolicy === 'enable_on_sku' || rule.skuPolicy === 'recommend_on_sku') {
    return SettingValue.NotSet
  }
  return SettingValue.Disabled
}

/**
 * Handle a SKU billing toggle change (Rules 3 and 1).
 *
 * Applies each feature's skuPolicy (Rule 3) to determine its new value,
 * then clamps it to the parent's state (Rule 1). Features are walked in
 * hierarchy order so parents are resolved before children.
 */
function handleSku(state: SecurityConfigurationSettings, action: SkuAction): SecurityConfigurationSettings {
  const settings = {...state}

  // Apply the user's SKU toggle change before propagating to individual features.
  setBillingToggle(action.sku, action.value, settings)

  // Walk features in this SKU in parent-first order.
  for (const rule of featureTree.featuresForSku(action.sku)) {
    const value = resolveSkuPolicy(rule, action.value, state)
    // ...then clamp it so a child can never be more permissive than its parent.
    settings[rule.feature] = rule.parent ? clampToParent(value, settings[rule.parent]) : value
  }

  return settings
}

/**
 * Handle a user toggling a single feature (Rules 1, 2, and 4).
 *
 * 1. Pull-up (Rule 2): enables all ancestors so a child isn't orphaned.
 * 2. Clamp-down (Rule 1): constrains descendants to the parent's level.
 * 3. SKU pull-up (Rule 4): auto-enables the billing toggle for paid features.
 * 4. Options (Rule 5): only written when explicitly supplied.
 */
function handleFeature(state: SecurityConfigurationSettings, action: FeatureAction): SecurityConfigurationSettings {
  const newSettings = {...state}
  newSettings[action.setting] = action.value

  // Rule 5 – Attach sub-feature options (e.g. codeScanningOptions) when the
  // caller provides them. We only write these when explicitly supplied so that
  // toggling a parent doesn't accidentally overwrite nested configuration.
  const featureOptionsKey = `${action.setting}Options`
  if (action.options && featureOptionsKey in state) {
    Object.assign(newSettings, {[featureOptionsKey]: action.options})
  }

  // Rule 2 – Parent pull-up: walk the full ancestor chain. If a parent is
  // currently Disabled and we're enabling a child, the parent must also be
  // enabled (since a disabled parent would otherwise clamp the child back
  // down). NotSet parents are only promoted when the child is set to Enabled.
  for (const ancestor of featureTree.ancestors(action.setting)) {
    const ancestorOldValue = state[ancestor]
    if (ancestorOldValue === SettingValue.Disabled) {
      newSettings[ancestor] = action.value
    } else if (ancestorOldValue === SettingValue.NotSet && action.value === SettingValue.Enabled) {
      newSettings[ancestor] = action.value
    }
  }

  // Rule 1 – Child clamp-down: breadth-first walk of all descendants.
  // Each child is adjusted so it never exceeds the permissiveness of its
  // (possibly just-changed) parent.
  clampDescendants(action.setting, newSettings)

  // Rule 4 – Auto-enable the billing toggle when a paid feature is turned on.
  if (action.sku && (action.value === SettingValue.Enabled || action.value === SettingValue.NotSet)) {
    if (action.value === SettingValue.Enabled || action.sku === 'bundled_ghas') {
      setBillingToggle(action.sku, SettingValue.Enabled, newSettings)
    } else {
      // Unbundled + NotSet: pull up from Disabled to NotSet, but don't
      // demote an already-enabled SKU.
      const key = action.sku === 'code_security' ? 'enableCodeSecurity' : 'enableSecretProtection'
      if (newSettings[key] === false) {
        setBillingToggle(action.sku, SettingValue.NotSet, newSettings)
      }
    }
  }

  return newSettings
}

/**
 * Reducer for the security configuration settings form.
 *
 * Handles two action types:
 *
 * - **SKU** — A SKU billing toggle changed (bundled GHAS or an individual SKU).
 *   Propagates to every feature in the SKU: enabling applies each feature's
 *   skuPolicy, disabling force-disables all, and not set resets to neutral.
 *
 * - **FEATURE** — A single feature toggle changed. Propagates upward (enabling
 *   ancestors so a child isn't orphaned) and downward (clamping descendants so
 *   no child is more permissive than its parent). Optionally auto-enables the
 *   billing toggle when a paid feature is turned on.
 */
export const settingsReducer = (state: SecurityConfigurationSettings, action: SettingsAction) => {
  switch (action.type) {
    case 'SKU':
      return handleSku(state, action)
    case 'FEATURE':
      return handleFeature(state, action)
    default:
      return state
  }
}

// Convenience wrappers that expose the handler functions directly (used by tests).
export function propagateSku(sku: Sku, value: SettingValue, state: SecurityConfigurationSettings) {
  return handleSku(state, {type: 'SKU', sku, value})
}

export function propagateFeature(
  setting: SecurityFeature,
  value: SettingValue,
  state: SecurityConfigurationSettings,
  opts?: {sku?: Sku; options?: SecuritySettingOptionsTypes},
) {
  return handleFeature(state, {type: 'FEATURE', setting, value, sku: opts?.sku, options: opts?.options})
}
