import {useState, type MouseEvent} from 'react'

import {ControlGroup} from '@github-ui/control-group'
import {Label} from '@primer/react'
import {useAppContext} from '../../../../contexts/AppContext'
import {updatePublicMonitoring} from '../../../../utils/api-helpers'
import Validation from '../../../Validation'

export interface PublicMonitoringProps {
  value: null | boolean
}

function PublicMonitoring({value}: PublicMonitoringProps) {
  const {enterprise} = useAppContext()
  const enterpriseSlug = enterprise!.slug
  const [publicMonitoring, setPublicMonitoring] = useState(value)
  const [error, setError] = useState<string | null>(null)

  const handleClick = async (e: MouseEvent<HTMLButtonElement>) => {
    e.preventDefault()

    const newValue = !publicMonitoring
    const resp = await updatePublicMonitoring(enterpriseSlug, {
      secret_scanning_public_monitoring: newValue ? 'enabled' : 'disabled',
    })

    if (resp?.success === true) {
      setPublicMonitoring(newValue)
      setError(null)
    } else {
      setError(resp?.error_message ?? 'Something went wrong, please try again.')
    }
  }

  return (
    typeof publicMonitoring === 'boolean' && (
      <ControlGroup.Item>
        <ControlGroup.Title id="public-monitoring">
          <div className="d-flex flex-items-center gap-2">
            <span>Public monitoring</span>
            <Label variant="success" size="small">
              Preview
            </Label>
          </div>
        </ControlGroup.Title>
        <ControlGroup.Description>
          Detect secrets in public GitHub repositories that may belong to your enterprise. Findings appear at the
          enterprise level.
          {error && <Validation validationStatus="error">{error}</Validation>}
        </ControlGroup.Description>
        <ControlGroup.ToggleSwitch
          data-testid="public-monitoring-toggle"
          aria-labelledby="public-monitoring"
          checked={publicMonitoring}
          onClick={handleClick}
        />
      </ControlGroup.Item>
    )
  )
}

export default PublicMonitoring
